css:
.ant-notes {
  /* re-theme with these four */
  --ant-notes-paper: oklch(0.975 0.008 85);
  --ant-notes-ink: oklch(0.25 0.02 60);
  --ant-notes-accent: oklch(0.6 0.165 38);
  --ant-notes-sheet: oklch(0.993 0.004 85);
  /* derived */
  --ant-notes-side: color-mix(in oklch, var(--ant-notes-ink) 4.5%, var(--ant-notes-paper));
  --ant-notes-line: color-mix(in oklch, var(--ant-notes-ink) 10%, transparent);
  --ant-notes-line2: color-mix(in oklch, var(--ant-notes-ink) 17%, transparent);
  --ant-notes-mute: color-mix(in oklch, var(--ant-notes-ink) 62%, var(--ant-notes-paper));
  --ant-notes-faint: color-mix(in oklch, var(--ant-notes-ink) 42%, var(--ant-notes-paper));
  --ant-notes-hover: color-mix(in oklch, var(--ant-notes-ink) 5%, transparent);
  --ant-notes-tint: color-mix(in oklch, var(--ant-notes-accent) 11%, var(--ant-notes-sheet));
  --ant-notes-mark: color-mix(in oklch, var(--ant-notes-accent) 24%, transparent);
  --ant-notes-ease: cubic-bezier(.2, .8, .2, 1);
  --ant-notes-spring: linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ant-notes-h, 680px); box-sizing: border-box;
  container-type: inline-size; overflow: clip; isolation: isolate;
  background: var(--ant-notes-paper); color: var(--ant-notes-ink); color-scheme: light; accent-color: var(--ant-notes-accent);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 14px;
  box-shadow: inset 0 0 0 1px var(--ant-notes-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ant-notes-accent); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .45; }
  & h2, & h3, & h4, & p, & ul, & ol, & dl, & dd, & blockquote { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 18px; padding: 3px 5px; text-align: center; border-radius: 5px; color: var(--ant-notes-faint); background: var(--ant-notes-sheet); box-shadow: inset 0 0 0 1px var(--ant-notes-line2), inset 0 -1.5px 0 var(--ant-notes-line2); }
  & mark { background: var(--ant-notes-mark); color: inherit; border-radius: 3px; padding: 0 1px; box-decoration-break: clone; }
}

.ant-notes .ant-notes-app {
  height: 100%; display: grid; grid-template-columns: 216px 300px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "side list ed";
}

/* ── sidebar ─────────────────────────────── */
.ant-notes .ant-notes-side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 14px; padding: 16px 12px 12px;
  background: var(--ant-notes-side); border-right: 1px solid var(--ant-notes-line); overflow-y: auto; scrollbar-width: none;
}
.ant-notes .ant-notes-brand {
  display: flex; align-items: center; gap: 10px; padding: 2px 6px 4px;
  & svg { width: 26px; height: 26px; color: var(--ant-notes-accent); stroke-width: 1.5; }
  & span { display: grid; line-height: 1.2; min-width: 0; }
  & b { font-size: 15px; font-weight: 780; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--ant-notes-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.ant-notes .ant-notes-new {
  display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 8px 0 11px; border-radius: 10px;
  background: var(--ant-notes-ink); color: var(--ant-notes-paper); font-weight: 650; font-size: 13px;
  box-shadow: 0 1px 0 color-mix(in oklch, var(--ant-notes-ink) 30%, transparent), 0 6px 14px -8px var(--ant-notes-ink);
  transition: scale .35s var(--ant-notes-spring), background .2s;
  & kbd { margin-left: auto; background: transparent; color: color-mix(in oklch, var(--ant-notes-paper) 70%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ant-notes-paper) 25%, transparent); }
  &:hover { background: color-mix(in oklch, var(--ant-notes-ink) 88%, var(--ant-notes-accent)); }
  &:active { scale: .97; }
}
.ant-notes .ant-notes-nav {
  display: grid; gap: 1px;
  & .sep { height: 1px; margin: 7px 8px; background: var(--ant-notes-line); }
  & .lbl { padding: 2px 8px 4px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ant-notes-faint); }
  & button {
    position: relative; display: flex; align-items: center; gap: 9px; height: 32px; padding: 0 8px; border-radius: 8px; text-align: left;
    font-size: 13px; font-weight: 520; color: var(--ant-notes-mute); transition: background .2s, color .2s;
    & svg { color: var(--ant-notes-faint); }
    & i { width: 9px; height: 9px; margin: 0 3.5px; border-radius: 3px; background: var(--c); flex: none; }
    & span { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & output { font: 500 11.5px/1 system-ui, sans-serif; font-variant-numeric: tabular-nums; color: var(--ant-notes-faint); }
    &:hover { background: var(--ant-notes-hover); color: var(--ant-notes-ink); }
    &[aria-current="true"] { background: var(--ant-notes-sheet); color: var(--ant-notes-ink); font-weight: 650; box-shadow: 0 0 0 1px var(--ant-notes-line), 0 2px 6px -3px color-mix(in oklch, var(--ant-notes-ink) 25%, transparent); }
    &[aria-current="true"] svg { color: var(--ant-notes-accent); }
  }
}
.ant-notes .ant-notes-tagbox {
  & h3 { padding: 2px 8px 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ant-notes-faint); }
}
.ant-notes .ant-notes-tags {
  display: flex; flex-wrap: wrap; gap: 5px; padding: 0 4px;
  & button {
    display: inline-flex; align-items: baseline; gap: 5px; padding: 4px 8px; border-radius: 99px; font-size: 12px; font-weight: 560;
    color: var(--ant-notes-mute); box-shadow: inset 0 0 0 1px var(--ant-notes-line2); transition: background .2s, color .2s, box-shadow .2s, scale .3s var(--ant-notes-spring);
    & small { font-size: 10.5px; font-variant-numeric: tabular-nums; color: var(--ant-notes-faint); }
    &:hover { background: var(--ant-notes-hover); color: var(--ant-notes-ink); }
    &:active { scale: .94; }
    &[aria-pressed="true"] { background: var(--ant-notes-accent); color: var(--ant-notes-sheet); box-shadow: none; }
    &[aria-pressed="true"] small { color: color-mix(in oklch, var(--ant-notes-sheet) 75%, transparent); }
  }
}
.ant-notes .ant-notes-keys {
  margin-top: auto; display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 8px; border-radius: 8px; font-size: 12px; color: var(--ant-notes-faint);
  & kbd { margin-left: auto; }
  &:hover, &[aria-expanded="true"] { background: var(--ant-notes-hover); color: var(--ant-notes-ink); }
}

/* ── list ─────────────────────────────── */
.ant-notes .ant-notes-list {
  grid-area: list; min-height: 0; display: flex; flex-direction: column; background: var(--ant-notes-sheet); border-right: 1px solid var(--ant-notes-line);
}
.ant-notes .ant-notes-lhead {
  display: flex; align-items: center; gap: 8px; padding: 16px 12px 10px 16px;
}
.ant-notes .ant-notes-ltitle {
  flex: 1; min-width: 0;
  & h2 { font-size: clamp(16px, 1.55cqi, 19px); font-weight: 760; letter-spacing: -.025em; line-height: 1.15; text-wrap: balance; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & p { font-size: 11.5px; color: var(--ant-notes-faint); font-variant-numeric: tabular-nums; }
}
.ant-notes .ant-notes-ibtn {
  display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--ant-notes-mute); flex: none;
  transition: background .2s, color .2s, scale .3s var(--ant-notes-spring);
  &:hover { background: var(--ant-notes-hover); color: var(--ant-notes-ink); }
  &:active { scale: .92; }
  &[aria-pressed="true"] { color: var(--ant-notes-accent); background: var(--ant-notes-tint); }
  &[aria-expanded="true"] { background: var(--ant-notes-hover); color: var(--ant-notes-ink); }
}
.ant-notes .ant-notes-drawerbtn, .ant-notes .ant-notes-back, .ant-notes .ant-notes-newsm { display: none; }
.ant-notes .ant-notes-search {
  display: flex; align-items: center; gap: 8px; margin: 0 12px 8px; height: 34px; padding: 0 7px 0 10px; border-radius: 9px; cursor: text;
  background: var(--ant-notes-paper); box-shadow: inset 0 0 0 1px var(--ant-notes-line); transition: box-shadow .2s, background .2s;
  & svg { color: var(--ant-notes-faint); }
  & input { flex: 1; min-width: 0; height: 100%; border: 0; background: none; outline: none; font-size: 13px; }
  & input::placeholder { color: var(--ant-notes-faint); }
  & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { background: var(--ant-notes-sheet); box-shadow: inset 0 0 0 1.5px var(--ant-notes-accent), 0 0 0 4px var(--ant-notes-mark); }
  &:focus-within kbd { opacity: 0; }
  & kbd { transition: opacity .2s; }
}
.ant-notes .ant-notes-active {
  display: flex; flex-wrap: wrap; gap: 5px; padding: 0 12px;
  &:not(:empty) { padding-bottom: 8px; }
  & button {
    display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 6px 0 9px; border-radius: 99px; font-size: 11.5px; font-weight: 600;
    background: var(--ant-notes-tint); color: color-mix(in oklch, var(--ant-notes-accent) 75%, var(--ant-notes-ink));
    & svg { width: 13px; height: 13px; }
    &:hover { background: var(--ant-notes-mark); }
  }
  & .clear { background: none; color: var(--ant-notes-faint); padding: 0 8px; }
  & .clear:hover { color: var(--ant-notes-ink); background: var(--ant-notes-hover); }
}
.ant-notes .ant-notes-rows {
  flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 0 8px 12px; scrollbar-width: thin; scrollbar-color: var(--ant-notes-line2) transparent;
  & .grp { padding: 10px 8px 5px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ant-notes-faint); display: flex; align-items: center; gap: 6px; }
  & .grp svg { width: 12px; height: 12px; }
}
.ant-notes .ant-notes-row {
  position: relative;
  & + .ant-notes-row::before { content: ""; position: absolute; left: 12px; right: 12px; top: 0; height: 1px; background: var(--ant-notes-line); transition: opacity .2s; }
  &:has(> button:hover)::before, &:has(> [aria-selected="true"])::before, &:has(> button:hover) + .ant-notes-row::before, &:has(> [aria-selected="true"]) + .ant-notes-row::before { opacity: 0; }
  & > button {
    position: relative; display: grid; gap: 2px; width: 100%; padding: 10px 12px 11px; border-radius: 10px; text-align: left; transition: background .2s;
    &:hover { background: var(--ant-notes-hover); }
    &[aria-selected="true"] { background: var(--ant-notes-tint); }
    &[aria-selected="true"]::after { content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--ant-notes-accent); }
  }
  & .t { display: flex; align-items: center; gap: 6px; font-size: 13.5px; font-weight: 650; letter-spacing: -.01em; min-width: 0; }
  & .t b { font-weight: inherit; flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .t svg { width: 13px; height: 13px; color: var(--ant-notes-accent); }
  & .s { font-size: 12.5px; color: var(--ant-notes-mute); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-wrap: pretty; }
  & .m { display: flex; align-items: center; gap: 6px; margin-top: 3px; font-size: 11px; color: var(--ant-notes-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; }
  & .m i { width: 7px; height: 7px; border-radius: 2px; background: var(--c); flex: none; }
  & .m em { font-style: normal; color: var(--ant-notes-mute); }
  & .m .tg { overflow: hidden; text-overflow: ellipsis; }
}
.ant-notes .ant-notes-empty {
  flex: 1; display: grid; place-content: center; justify-items: center; gap: 10px; padding: 24px; text-align: center; color: var(--ant-notes-mute);
  & svg { width: 28px; height: 28px; color: var(--ant-notes-faint); stroke-width: 1.4; }
  & b { color: var(--ant-notes-ink); font-size: 14px; font-weight: 680; text-wrap: balance; }
  & p { font-size: 12.5px; max-width: 26ch; text-wrap: pretty; }
  & button { margin-top: 4px; height: 30px; padding: 0 12px; border-radius: 8px; font-weight: 620; box-shadow: inset 0 0 0 1px var(--ant-notes-line2); }
  & button:hover { background: var(--ant-notes-hover); }
}

/* ── editor ─────────────────────────────── */
.ant-notes .ant-notes-ed {
  grid-area: ed; min-height: 0; min-width: 0; display: flex; flex-direction: column; background: var(--ant-notes-paper); timeline-scope: --ant-notes-ed;
}
.ant-notes .ant-notes-bar {
  position: relative; z-index: 2; display: flex; align-items: center; gap: 6px; height: 54px; padding: 0 12px 0 18px; flex: none;
  border-bottom: 1px solid transparent; background: var(--ant-notes-paper);
}
.ant-notes .ant-notes-crumb {
  display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 6px 0 9px; border-radius: 8px; font-size: 12.5px; font-weight: 600; color: var(--ant-notes-mute);
  & i { width: 8px; height: 8px; border-radius: 2.5px; background: var(--c, var(--ant-notes-faint)); }
  & svg { width: 14px; height: 14px; color: var(--ant-notes-faint); transition: rotate .3s var(--ant-notes-ease); }
  &:hover { background: var(--ant-notes-hover); color: var(--ant-notes-ink); }
  &[aria-expanded="true"] { background: var(--ant-notes-hover); }
  &[aria-expanded="true"] svg { rotate: 180deg; }
  &:disabled { opacity: .55; }
}
.ant-notes .ant-notes-mode {
  position: relative; display: flex; align-items: center; gap: 2px; padding: 3px; margin-left: 4px; border-radius: 10px; background: var(--ant-notes-hover);
  & button { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--ant-notes-mute); transition: color .2s; }
  & button svg { width: 14px; height: 14px; }
  & button[aria-pressed="true"] { color: var(--ant-notes-ink); }
  & button:hover { color: var(--ant-notes-ink); }
  & kbd { margin: 0 4px 0 2px; }
  &::before {
    content: ""; position: absolute; top: 3px; bottom: 3px; left: 3px; width: var(--w, 64px); translate: var(--x, 0) 0; border-radius: 7px;
    background: var(--ant-notes-sheet); box-shadow: 0 1px 2px color-mix(in oklch, var(--ant-notes-ink) 18%, transparent), 0 0 0 1px var(--ant-notes-line);
    transition: translate .45s var(--ant-notes-spring), width .45s var(--ant-notes-spring);
  }
}
.ant-notes .ant-notes-grow { flex: 1; }
.ant-notes .ant-notes-tools { display: flex; align-items: center; gap: 2px; }
.ant-notes .ant-notes-tools .txt {
  display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 8px; font-size: 12.5px; font-weight: 620; color: var(--ant-notes-mute);
  &:hover { background: var(--ant-notes-hover); color: var(--ant-notes-ink); }
  &.danger { color: oklch(0.55 0.19 27); }
  &.danger:hover { background: color-mix(in oklch, oklch(0.55 0.19 27) 10%, transparent); }
}
.ant-notes .ant-notes-scroll {
  flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scroll-timeline: --ant-notes-ed y;
  scrollbar-width: thin; scrollbar-color: var(--ant-notes-line2) transparent;
}
@supports (animation-timeline: scroll()) {
  .ant-notes .ant-notes-bar { animation: ant-notes-rule linear both; animation-timeline: --ant-notes-ed; animation-range: 0 40px; }
}
@keyframes ant-notes-rule { to { border-bottom-color: var(--ant-notes-line); box-shadow: 0 8px 18px -16px var(--ant-notes-ink); } }

.ant-notes .ant-notes-doc {
  max-width: 68ch; margin: 0 auto; padding: 14px clamp(18px, 4cqi, 52px) 40px; min-height: 100%; display: flex; flex-direction: column;
}
.ant-notes .ant-notes-title {
  width: 100%; border: 0; background: none; outline: none; padding: 0; font-size: clamp(22px, 2.5cqi, 30px); font-weight: 780; letter-spacing: -.03em; line-height: 1.2;
  &::placeholder { color: var(--ant-notes-faint); }
}
.ant-notes .ant-notes-meta {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin: 10px 0 18px; font-size: 12px; color: var(--ant-notes-faint);
  & .chip { display: inline-flex; align-items: center; gap: 2px; height: 24px; padding: 0 3px 0 9px; border-radius: 99px; font-weight: 600; color: var(--ant-notes-mute); background: var(--ant-notes-hover); }
  & .chip button { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 50%; color: var(--ant-notes-faint); }
  & .chip button:hover { background: var(--ant-notes-line2); color: var(--ant-notes-ink); }
  & .chip svg { width: 12px; height: 12px; stroke-width: 2; }
  & .add { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 9px 0 7px; border-radius: 99px; font-weight: 600; color: var(--ant-notes-faint); box-shadow: inset 0 0 0 1px var(--ant-notes-line2); }
  & .add svg { width: 13px; height: 13px; }
  & .add:hover { color: var(--ant-notes-ink); background: var(--ant-notes-hover); }
  & input { height: 24px; width: 120px; padding: 0 9px; border: 0; border-radius: 99px; outline: none; font-size: 12px; background: var(--ant-notes-sheet); box-shadow: inset 0 0 0 1.5px var(--ant-notes-accent); }
}
.ant-notes .ant-notes-body {
  flex: 1; width: 100%; min-height: 320px; resize: none; border: 0; outline: none; background: none; padding: 0;
  font: 14.5px/1.7 ui-monospace, Menlo, monospace; font-size: 13.5px; color: var(--ant-notes-ink); tab-size: 2;
  &::placeholder { color: var(--ant-notes-faint); }
}
.ant-notes .ant-notes-md {
  font-size: 14.5px; line-height: 1.68; color: color-mix(in oklch, var(--ant-notes-ink) 92%, var(--ant-notes-paper)); cursor: text;
  & > * + * { margin-top: .6em; }
  & h2 { font-size: 1.32em; font-weight: 760; letter-spacing: -.02em; line-height: 1.25; margin-top: 1.3em; text-wrap: balance; color: var(--ant-notes-ink); }
  & h3 { font-size: 11.5px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; margin-top: 1.9em; color: var(--ant-notes-accent); }
  & h3 + *, & h2 + * { margin-top: .45em; }
  & h4 { font-size: 1em; font-weight: 700; margin-top: 1.2em; }
  & p { text-wrap: pretty; }
  & strong { font-weight: 680; color: var(--ant-notes-ink); }
  & code { font: .88em ui-monospace, Menlo, monospace; padding: 1px 5px; border-radius: 5px; background: var(--ant-notes-hover); }
  & blockquote { padding: 2px 0 2px 14px; border-left: 2px solid var(--ant-notes-accent); color: var(--ant-notes-mute); font-style: italic; text-wrap: pretty; }
  & ul:not(.tasks) > li, & ol > li { position: relative; padding-left: 22px; }
  & ul:not(.tasks) > li + li, & ol > li + li, & .tasks > li + li { margin-top: .3em; }
  & ul:not(.tasks) > li::before { content: ""; position: absolute; left: 7px; top: .72em; width: 5px; height: 5px; border-radius: 50%; background: var(--ant-notes-faint); }
  & ol { counter-reset: ant-notes-ol; }
  & ol > li { counter-increment: ant-notes-ol; }
  & ol > li::before { content: counter(ant-notes-ol); position: absolute; left: 0; top: .18em; font: 600 11px/1.6 ui-monospace, Menlo, monospace; color: var(--ant-notes-accent); font-variant-numeric: tabular-nums; }
  & .tasks > li { display: flex; align-items: flex-start; gap: 10px; transition: color .3s; }
  & .tasks > li.done > span { color: var(--ant-notes-faint); text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--ant-notes-ink) 35%, transparent); }
  & .ph { color: var(--ant-notes-faint); font-style: italic; }
}
.ant-notes .ant-notes-cb {
  flex: none; display: grid; place-items: center; width: 17px; height: 17px; margin-top: .26em; border-radius: 5px;
  box-shadow: inset 0 0 0 1.5px var(--ant-notes-line2); background: var(--ant-notes-sheet);
  transition: background .25s, box-shadow .25s, scale .35s var(--ant-notes-spring);
  & svg { width: 13px; height: 13px; stroke-width: 2.6; color: var(--ant-notes-sheet); stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .35s var(--ant-notes-ease) .05s; }
  &:hover { box-shadow: inset 0 0 0 1.5px var(--ant-notes-accent); }
  &:active { scale: .85; }
  &[aria-checked="true"] { background: var(--ant-notes-accent); box-shadow: none; }
  &[aria-checked="true"] svg { stroke-dashoffset: 0; }
}
.ant-notes .ant-notes-noed {
  flex: 1; display: grid; place-content: center; justify-items: center; gap: 10px; text-align: center; color: var(--ant-notes-mute);
  & svg { width: 34px; height: 34px; stroke-width: 1.3; color: var(--ant-notes-faint); }
  & b { font-size: 15px; color: var(--ant-notes-ink); }
