  const item = (k, icon, name, count, extra) => '<button type="button" data-k="v-' + k + '" data-view="' + k + '" aria-current="' + (S.view === k) + '"' + (extra || '') + '>' + icon + '<span>' + name + '</span><output>' + count + '</output></button>';
  keep($('[data-nav]'), () => {
    $('[data-nav]').innerHTML =
      item('all', I.all, 'All notes', live.length) + item('pinned', I.pin, 'Pinned', live.filter(n => n.pinned).length) +
      '<div class="sep"></div><div class="lbl">Folders</div>' +
      FOLDERS.map(f => item(f.id, '<i style="--c:' + f.c + '"></i>', esc(f.name), live.filter(n => n.folder === f.id).length)).join('') +
      '<div class="sep"></div>' + item('trash', I.trash, 'Trash', notes.filter(n => n.trashed).length);
