    $('[data-tags]').innerHTML = tags.map(t => '<button type="button" data-k="t-' + esc(t) + '" data-tag="' + esc(t) + '" aria-pressed="' + S.tags.has(t) + '">#' + esc(t) + '<small>' + counts[t] + '</small></button>').join('');
  });
}

/* ── list (keyed, FLIP) ── */
const rowEls = new Map();
function rowSig(n, words) { return [n.title, n.body, n.edited, n.folder, n.pinned, n.tags.join(), words.join(), S.view === 'trash'].join('|'); }
