    '<span class="t"><b>' + (hl(esc(n.title || 'Untitled'), words)) + '</b>' + (n.pinned && S.view !== 'trash' ? I.pin : '') + '</span>' +
    '<span class="s">' + (snippet(n, words) || '<em>No text</em>') + '</span>' +
    '<span class="m"><time>' + when(n.edited) + '</time><i style="--c:' + f.c + '"></i><em>' + esc(f.name) + '</em>' +
    (n.tags.length ? '<span class="tg">· ' + n.tags.map(t => '#' + esc(t)).join(' ') + '</span>' : '') + '</span></button>';
