      : '<button type="button" class="ant-notes-ibtn" data-k="pin" data-act="pin" aria-pressed="' + n.pinned + '" aria-label="' + (n.pinned ? 'Unpin' : 'Pin') + ' note (P)" title="' + (n.pinned ? 'Unpin' : 'Pin') + ' (P)">' + I.pin + '</button>' +
