}
function ensureSel() { const vis = visible(); if (!vis.some(n => n.id === S.sel)) S.sel = vis.length ? vis[0].id : null; }
function setView(v) {
  S.view = v; ensureSel(); root.dataset.drawer = 'closed'; syncDrawer();
  renderAll(true);
}
function setMode(m, focus) {
  const n = cur(); if (!n || (n.trashed && m === 'write')) return;
