}
function focusSel() { const b = $('[data-rows] [aria-selected="true"]') || $('[data-rows] [role=option]'); if (b) b.focus({ preventScroll: false }); }

/* toast */
let tt = 0;
function toast(msg, canUndo) {
  const t = $('[data-toast]');
  $('[data-tmsg]').textContent = msg; t.classList.toggle('no-undo', !canUndo);
  t.hidden = false; clearTimeout(tt); tt = setTimeout(() => { t.hidden = true; }, 4200);
}

/* menus */
function openMenu(kind, trigger) {
  closeMenu(true);
  const m = $('[data-menu]'), n = cur();
  if (kind === 'sort') {
    m.setAttribute('aria-label', 'Sort notes');
    m.innerHTML = '<div class="h">Sort by</div>' + [['edited', 'Date edited'], ['created', 'Date created'], ['title', 'Title']].map(([k, l]) =>
      '<button type="button" role="menuitemradio" aria-checked="' + (S.sort === k) + '" data-sort="' + k + '">' + l + '<span class="ck">' + I.check + '</span></button>').join('');
  } else {
    if (!n) return;
    m.setAttribute('aria-label', 'Move to folder');
    m.innerHTML = '<div class="h">Move to</div>' + FOLDERS.map(f =>
      '<button type="button" role="menuitemradio" aria-checked="' + (n.folder === f.id) + '" data-moveto="' + f.id + '"><i style="--c:' + f.c + '"></i>' + esc(f.name) + '<span class="ck">' + I.check + '</span></button>').join('');
  }
  const rr = root.getBoundingClientRect(), tr = trigger.getBoundingClientRect();
  m.hidden = false;
  const w = m.offsetWidth, left = Math.min(Math.max(8, tr.left - rr.left + (kind === 'sort' ? tr.width - w : 0)), rr.width - w - 8);
  m.style.left = left + 'px'; m.style.top = (tr.bottom - rr.top + 6) + 'px';
  m.style.setProperty('--ox', kind === 'sort' ? 'top right' : 'top left');
