}
function syncDrawer() { const b = $('[data-act="drawer"]'); b.setAttribute('aria-expanded', root.dataset.drawer === 'open'); }

/* ── events ── */
root.addEventListener('click', e => {
  const t = e.target.closest('button'); if (!t || !root.contains(t)) return;
  if (S.menu && !t.closest('[data-menu]') && t !== S.menu.trigger) closeMenu(true);
  const d = t.dataset;
  if (d.view) return setView(d.view);
  if (d.tag) { S.tags.has(d.tag) ? S.tags.delete(d.tag) : S.tags.add(d.tag); ensureSel(); return renderAll(true); }
  if (d.untag) { S.tags.delete(d.untag); ensureSel(); return renderAll(true); }
  if (d.open) return select(d.open, true);
  if (d.mode) return setMode(d.mode);
  if (d.sort) { S.sort = d.sort; closeMenu(); renderList(); return toast('Sorted by ' + t.textContent.trim().toLowerCase(), false); }
  if (d.moveto) {
    const n = cur(); closeMenu();
    if (!n) return toast('Select a note to move first', false);
    if (n.folder === d.moveto) return toast('Already in ' + FO[d.moveto].name, false);
    remember('Moved'); n.folder = d.moveto; touch(n);
    if (!inView(n)) { ensureSel(); }
    renderAll(!inView(n)); return toast('Moved to ' + FO[d.moveto].name, true);
  }
  if (d.rmtag) { const n = cur(); if (!n) return; remember('Removed #' + d.rmtag); n.tags = n.tags.filter(x => x !== d.rmtag); touch(n); renderMeta(); renderSide(); renderList(); renderFoot(); return toast('Removed #' + d.rmtag, true); }
  if (t.classList.contains('ant-notes-cb')) {
    const n = cur(); if (!n) return;
    const lines = n.body.split('\n'), i = +d.line;
    lines[i] = lines[i].replace(/\[( |x|X)\]/, m => m === '[ ]' ? '[x]' : '[ ]');
    n.body = lines.join('\n'); touch(n);
    t.setAttribute('aria-checked', t.getAttribute('aria-checked') !== 'true');
    t.parentElement.classList.toggle('done', t.getAttribute('aria-checked') === 'true');
    renderFoot(); renderList(false); return;
  }
  switch (d.act) {
    case 'new': return newNote();
    case 'help': { const h = $('[data-help]'); h.hidden = !h.hidden; t.setAttribute('aria-expanded', !h.hidden); if (!h.hidden) $('[data-act="help-close"]').focus({ preventScroll: true }); return; }
    case 'help-close': return closeHelp(true);
    case 'sort': return S.menu && S.menu.kind === 'sort' ? closeMenu() : openMenu('sort', t);
    case 'move': return S.menu && S.menu.kind === 'move' ? closeMenu() : openMenu('move', t);
    case 'pin': return togglePin();
    case 'delete': return trashCur();
    case 'undo': $('[data-toast]').hidden = true; return undo();
    case 'restore': { const n = cur(); if (!n) return; remember('Restored'); n.trashed = false; ensureSel(); renderAll(true); return toast('Restored to ' + FO[n.folder].name, true); }
    case 'purge': { const n = cur(); if (!n) return; remember('Deleted forever'); const vis = visible(), i = vis.indexOf(n); notes = notes.filter(x => x !== n); const nx = vis[i + 1] || vis[i - 1]; S.sel = nx ? nx.id : null; renderAll(true); return toast('Deleted “' + (n.title || 'Untitled') + '” forever', true); }
    case 'addtag': {
      const inp = root.ownerDocument.createElement('input');
      inp.placeholder = 'tag name'; inp.setAttribute('aria-label', 'New tag'); inp.dataset.newtag = '1';
      t.replaceWith(inp); inp.focus(); return;
    }
    case 'reset-search': S.q = ''; $('[data-q]').value = ''; S.tags.clear(); ensureSel(); return renderAll(true);
    case 'clear-tags': S.tags.clear(); ensureSel(); return renderAll(true);
    case 'drawer': root.dataset.drawer = root.dataset.drawer === 'open' ? 'closed' : 'open'; syncDrawer(); if (root.dataset.drawer === 'open') { const b = $('[data-nav] [aria-current="true"]'); if (b) b.focus({ preventScroll: true }); } return;
    case 'scrim': root.dataset.drawer = 'closed'; syncDrawer(); return;
