  }
});
function closeHelp(refocus) { const h = $('[data-help]'); if (h.hidden) return; h.hidden = true; $('[data-act="help"]').setAttribute('aria-expanded', 'false'); if (refocus) $('[data-act="help"]').focus({ preventScroll: true }); }
root.addEventListener('pointerdown', e => {
  if (S.menu && !e.target.closest('[data-menu]') && !e.target.closest('[aria-haspopup]')) closeMenu(true);
  if (!e.target.closest('[data-help]') && !e.target.closest('[data-act="help"]')) closeHelp(false);
