root.addEventListener('focusout', e => { if (e.target.dataset && e.target.dataset.newtag && e.target.isConnected) commitTag(e.target); });
root.addEventListener('input', e => {
  const t = e.target, n = cur();
  if (t.matches('[data-q]')) { S.q = t.value; ensureSel(); renderList(); renderSide(); renderEditor(false); return; }
  if (!n) return;
  if (t.matches('[data-title]')) { n.title = t.value; touch(n); renderList(false); renderFoot(); return; }
  if (t.matches('[data-body]')) { n.body = t.value; touch(n); renderList(false); renderFoot(); }
});
root.addEventListener('keydown', e => {
  const t = e.target, k = e.key;
  if (S.menu) {
    const items = $$('[data-menu] button'), i = items.indexOf(root.ownerDocument.activeElement);
    if (k === 'ArrowDown' || k === 'ArrowUp') { e.preventDefault(); items[(i + (k === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus(); return; }
    if (k === 'Home' || k === 'End') { e.preventDefault(); items[k === 'Home' ? 0 : items.length - 1].focus(); return; }
    if (k === 'Escape' || k === 'Tab') { e.preventDefault(); closeMenu(); return; }
    return;
  }
  if (t.dataset && t.dataset.newtag) {
    if (k === 'Enter') { e.preventDefault(); t.dataset.refocus = '1'; commitTag(t); }
