    return;
  }
  if (k === 'Escape') {
    if (!$('[data-help]').hidden) return closeHelp(true);
    if (root.dataset.drawer === 'open') { root.dataset.drawer = 'closed'; syncDrawer(); return; }
    if (t.matches('[data-q]')) { if (t.value) { t.value = ''; S.q = ''; ensureSel(); renderAll(false); } else focusSel(); return; }
    if (t.matches('[data-body]')) { setMode('read', false); return focusSel(); }
    if (t.matches('[data-title]')) return focusSel();
    if (root.dataset.pane === 'ed') { root.dataset.pane = 'list'; return focusSel(); }
    return;
