@property --ant-tasks-goal { syntax: "<number>"; inherits: true; initial-value: 0; }
.ant-tasks {
  /* re-theme with these four */
  --ant-tasks-bg: oklch(0.19 0.008 255);
  --ant-tasks-ink: oklch(0.95 0.006 255);
  --ant-tasks-accent: oklch(0.84 0.13 166);
  --ant-tasks-panel: oklch(0.225 0.01 255);
  /* priorities */
  --ant-tasks-p1: oklch(0.7 0.19 26);
  --ant-tasks-p2: oklch(0.8 0.15 72);
  --ant-tasks-p3: oklch(0.73 0.12 248);
  --ant-tasks-p4: color-mix(in oklch, var(--ant-tasks-ink) 34%, var(--ant-tasks-bg));
  /* derived */
  --ant-tasks-line: color-mix(in oklch, var(--ant-tasks-ink) 8%, transparent);
  --ant-tasks-line2: color-mix(in oklch, var(--ant-tasks-ink) 15%, transparent);
  --ant-tasks-hover: color-mix(in oklch, var(--ant-tasks-ink) 5%, transparent);
  --ant-tasks-mute: color-mix(in oklch, var(--ant-tasks-ink) 62%, var(--ant-tasks-bg));
  --ant-tasks-faint: color-mix(in oklch, var(--ant-tasks-ink) 40%, var(--ant-tasks-bg));
  --ant-tasks-tint: color-mix(in oklch, var(--ant-tasks-accent) 13%, transparent);
  --ant-tasks-on: oklch(0.2 0.03 170);
  --ant-tasks-ease: cubic-bezier(.2, .8, .2, 1);
  --ant-tasks-spring: linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ant-tasks-h, 680px); box-sizing: border-box;
  container-type: inline-size; overflow: clip; isolation: isolate; border-radius: 16px;
  background: var(--ant-tasks-bg); color: var(--ant-tasks-ink); color-scheme: dark; accent-color: var(--ant-tasks-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ant-tasks-accent); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & h4, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-block; min-width: 17px; padding: 2px 4px; border-radius: 4px; text-align: center; font: 600 10px/1.2 ui-monospace, Menlo, monospace; color: var(--ant-tasks-mute); box-shadow: inset 0 0 0 1px var(--ant-tasks-line2), inset 0 -1.5px 0 var(--ant-tasks-line2); }
}
.ant-tasks .ant-tasks-app {
  height: 100%; display: grid; grid-template-columns: 214px minmax(0, 1fr) 328px; grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "side main detail";
}

/* ── side ── */
.ant-tasks .ant-tasks-side {
  grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 16px;
  padding: 16px 10px 12px; border-right: 1px solid var(--ant-tasks-line);
}
.ant-tasks .ant-tasks-brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px;
  & svg { width: 26px; height: 26px; color: var(--ant-tasks-accent); stroke-width: 1.8; }
  & span { display: grid; line-height: 1.2; }
  & b { font-size: 15px; font-weight: 780; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--ant-tasks-faint); }
}
.ant-tasks .ant-tasks-sec h3 { padding: 0 8px 5px; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--ant-tasks-faint); }
.ant-tasks .ant-tasks-nav {
  display: grid; gap: 1px;
  & button {
    display: flex; align-items: center; gap: 9px; height: 32px; padding: 0 8px; border-radius: 8px; text-align: left; font-weight: 540; color: var(--ant-tasks-mute);
    transition: background .2s, color .2s;
    & svg { color: var(--ant-tasks-faint); transition: color .2s; }
    & .dot { width: 10px; height: 10px; margin: 0 3px; border-radius: 50%; box-shadow: inset 0 0 0 2.5px var(--c); flex: none; }
    & span { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & output { font-size: 11.5px; font-variant-numeric: tabular-nums; color: var(--ant-tasks-faint); }
    & output.hot { color: var(--ant-tasks-p1); font-weight: 650; }
    &:hover { background: var(--ant-tasks-hover); color: var(--ant-tasks-ink); }
    &[aria-current="true"] { background: var(--ant-tasks-tint); color: var(--ant-tasks-ink); font-weight: 650; }
    &[aria-current="true"] svg { color: var(--ant-tasks-accent); }
    &[aria-current="true"] .dot { background: var(--c); }
  }
}
.ant-tasks .ant-tasks-labels {
  display: flex; flex-wrap: wrap; gap: 4px; padding: 0 4px;
  & button { height: 24px; padding: 0 8px; border-radius: 6px; font-size: 12px; font-weight: 560; color: var(--ant-tasks-mute); box-shadow: inset 0 0 0 1px var(--ant-tasks-line2); transition: background .2s, color .2s; }
  & button:hover { color: var(--ant-tasks-ink); background: var(--ant-tasks-hover); }
  & button[aria-current="true"] { background: var(--ant-tasks-ink); color: var(--ant-tasks-bg); box-shadow: none; }
}
.ant-tasks .ant-tasks-goal {
  margin-top: auto; display: flex; align-items: center; gap: 11px; padding: 10px; border-radius: 12px; background: var(--ant-tasks-hover);
  & .ring {
    --ant-tasks-goal: var(--g, 0); position: relative; width: 38px; height: 38px; border-radius: 50%; flex: none;
    background: conic-gradient(var(--ant-tasks-accent) calc(var(--ant-tasks-goal) * 1turn), var(--ant-tasks-line2) 0);
    mask: radial-gradient(farthest-side, transparent calc(100% - 5px), #000 calc(100% - 4.5px));
    transition: --ant-tasks-goal .9s var(--ant-tasks-ease);
  }
  & .num { position: absolute; width: 38px; text-align: center; font: 700 11px/38px system-ui, sans-serif; font-variant-numeric: tabular-nums; }
  & .rw { position: relative; }
  & b { display: block; font-size: 12.5px; font-weight: 650; }
  & small { font-size: 11px; color: var(--ant-tasks-faint); }
  &.met .ring { background: var(--ant-tasks-accent); }
}

/* ── main ── */
.ant-tasks .ant-tasks-main { grid-area: main; min-height: 0; min-width: 0; display: flex; flex-direction: column; }
.ant-tasks .ant-tasks-head { display: flex; align-items: flex-end; gap: 12px; padding: 20px 22px 12px; }
.ant-tasks .ant-tasks-htitle {
  flex: 1; min-width: 0;
  & h2 { font-size: clamp(20px, 2.2cqi, 26px); font-weight: 780; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
  & p { margin-top: 3px; font-size: 12px; color: var(--ant-tasks-faint); font-variant-numeric: tabular-nums; }
}
.ant-tasks .ant-tasks-hact { display: flex; gap: 6px; }
.ant-tasks .ant-tasks-pill {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px 0 8px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--ant-tasks-mute);
  box-shadow: inset 0 0 0 1px var(--ant-tasks-line2); transition: background .2s, color .2s;
  & svg { width: 14px; height: 14px; }
  &:hover { color: var(--ant-tasks-ink); background: var(--ant-tasks-hover); }
}
.ant-tasks .ant-tasks-switch {
  display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 10px 0 6px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--ant-tasks-mute);
  box-shadow: inset 0 0 0 1px var(--ant-tasks-line2);
  & i { position: relative; width: 26px; height: 16px; border-radius: 9px; background: var(--ant-tasks-line2); transition: background .25s; }
  & i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--ant-tasks-ink); transition: translate .4s var(--ant-tasks-spring); }
  &[aria-checked="true"] { color: var(--ant-tasks-ink); }
  &[aria-checked="true"] i { background: var(--ant-tasks-accent); }
  &[aria-checked="true"] i::after { translate: 10px 0; background: var(--ant-tasks-on); }
  &:hover { background: var(--ant-tasks-hover); }
}

/* quick add with token mirror */
.ant-tasks .ant-tasks-qa { padding: 0 22px 6px; }
.ant-tasks .ant-tasks-field {
  display: flex; align-items: center; gap: 10px; height: 44px; padding: 0 6px 0 12px; border-radius: 12px; background: var(--ant-tasks-panel);
  box-shadow: inset 0 0 0 1px var(--ant-tasks-line2); transition: box-shadow .25s, background .25s;
  & > svg { color: var(--ant-tasks-accent); }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--ant-tasks-accent), 0 0 0 4px var(--ant-tasks-tint); }
  &:focus-within kbd { opacity: 0; }
  & kbd { transition: opacity .2s; }
  &.bad { box-shadow: inset 0 0 0 1.5px var(--ant-tasks-p1); animation: ant-tasks-shake .4s var(--ant-tasks-ease); }
}
@keyframes ant-tasks-shake { 20%, 60% { translate: -4px 0; } 40%, 80% { translate: 4px 0; } }
.ant-tasks .ant-tasks-inwrap { position: relative; flex: 1; min-width: 0; height: 100%; }
.ant-tasks .ant-tasks-inwrap input, .ant-tasks .ant-tasks-mirror {
  position: absolute; inset: 0; width: 100%; height: 100%; padding: 0; margin: 0; border: 0;
  font: 500 14px/44px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; letter-spacing: 0; white-space: pre; word-spacing: 0;
}
.ant-tasks .ant-tasks-inwrap input { background: transparent; outline: none; z-index: 1; caret-color: var(--ant-tasks-accent); }
.ant-tasks .ant-tasks-inwrap input::placeholder { color: var(--ant-tasks-faint); }
.ant-tasks .ant-tasks-mirror {
  overflow: hidden; color: transparent; pointer-events: none;
  & mark { color: transparent; border-radius: 4px; background: var(--tk); box-shadow: 0 0 0 2px var(--tk); animation: ant-tasks-tok .35s var(--ant-tasks-ease); }
  & .k-date { --tk: color-mix(in oklch, var(--ant-tasks-accent) 26%, transparent); }
  & .k-time { --tk: color-mix(in oklch, var(--ant-tasks-accent) 26%, transparent); }
  & .k-rec { --tk: color-mix(in oklch, var(--ant-tasks-accent) 18%, transparent); }
  & .k-prio { --tk: color-mix(in oklch, var(--pc) 32%, transparent); }
  & .k-proj { --tk: color-mix(in oklch, var(--pc) 30%, transparent); }
  & .k-label { --tk: color-mix(in oklch, var(--ant-tasks-ink) 16%, transparent); }
  & .k-bad { --tk: transparent; background: none; box-shadow: none; text-decoration: underline wavy var(--ant-tasks-p1) 1.5px; text-underline-offset: 6px; text-decoration-skip-ink: none; color: transparent; }
}
@keyframes ant-tasks-tok { from { box-shadow: 0 0 0 6px transparent; background: transparent; } }
.ant-tasks .ant-tasks-add {
  height: 32px; padding: 0 14px; border-radius: 8px; font-weight: 700; font-size: 12.5px; background: var(--ant-tasks-accent); color: var(--ant-tasks-on);
  transition: scale .3s var(--ant-tasks-spring), filter .2s;
  &:hover { filter: brightness(1.06); }
  &:active { scale: .94; }
}
.ant-tasks .ant-tasks-parse {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px; min-height: 34px; padding: 7px 2px 0; font-size: 12px; color: var(--ant-tasks-faint);
  & .lead { margin-right: 2px; }
  & .err { color: var(--ant-tasks-p1); font-weight: 560; }
  & .chip {
    display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 4px 0 8px; border-radius: 7px; font-weight: 600; color: var(--ant-tasks-ink);
    background: var(--ant-tasks-hover); box-shadow: inset 0 0 0 1px var(--ant-tasks-line);
    animation: ant-tasks-pop .4s var(--ant-tasks-spring) both; animation-delay: calc(var(--i, 0) * 40ms);
    & svg { width: 13px; height: 13px; color: var(--c, var(--ant-tasks-accent)); }
    & em { font-style: normal; font-weight: 500; color: var(--ant-tasks-faint); }
    & button { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 5px; color: var(--ant-tasks-faint); }
    & button svg { width: 11px; height: 11px; color: currentColor; stroke-width: 2.2; }
    & button:hover { background: var(--ant-tasks-line2); color: var(--ant-tasks-ink); }
  }
  & .try {
    height: 24px; padding: 0 9px; border-radius: 7px; font-size: 12px; color: var(--ant-tasks-mute); box-shadow: inset 0 0 0 1px var(--ant-tasks-line2); transition: background .2s, color .2s;
    &:hover { background: var(--ant-tasks-hover); color: var(--ant-tasks-ink); }
    & q { quotes: none; font-family: ui-monospace, Menlo, monospace; font-size: 11.5px; }
  }
}
@keyframes ant-tasks-pop { from { opacity: 0; scale: .8; } }

/* list */
.ant-tasks .ant-tasks-scroll { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 4px 14px 18px; scrollbar-width: thin; scrollbar-color: var(--ant-tasks-line2) transparent; }
.ant-tasks .ant-tasks-grp {
  & + .ant-tasks-grp { margin-top: 12px; }
  & > header {
    position: sticky; top: -4px; z-index: 2; display: flex; align-items: center; gap: 8px; padding: 9px 8px 7px; background: var(--ant-tasks-bg);
    border-bottom: 1px solid var(--ant-tasks-line);
    & h3 { font-size: 12.5px; font-weight: 720; letter-spacing: -.005em; }
    & h3 em { font-style: normal; font-weight: 500; color: var(--ant-tasks-faint); margin-left: 4px; }
    & output { font-size: 11.5px; color: var(--ant-tasks-faint); font-variant-numeric: tabular-nums; }
    & .act { margin-left: auto; height: 24px; padding: 0 8px; border-radius: 6px; font-size: 11.5px; font-weight: 650; color: var(--ant-tasks-accent); }
    & .act:hover { background: var(--ant-tasks-tint); }
  }
  &.over > header h3 { color: var(--ant-tasks-p1); }
  & .none { display: flex; align-items: center; gap: 8px; padding: 8px 10px; font-size: 12px; color: var(--ant-tasks-faint); }
  & .none button { color: var(--ant-tasks-mute); font-weight: 600; padding: 2px 6px; border-radius: 6px; }
  & .none button:hover { background: var(--ant-tasks-hover); color: var(--ant-tasks-ink); }
}
.ant-tasks .ant-tasks-item {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: start; gap: 10px; padding: 9px 8px 9px 10px; border-radius: 10px;
  transition: background .2s;
  & + .ant-tasks-item { box-shadow: 0 -1px 0 var(--ant-tasks-line); }
  &:hover { background: var(--ant-tasks-hover); }
  &[aria-current="true"] { background: var(--ant-tasks-tint); box-shadow: none; }
  &[aria-current="true"] + .ant-tasks-item { box-shadow: none; }
  &.flash { animation: ant-tasks-flash 1.4s var(--ant-tasks-ease); }
}
@keyframes ant-tasks-flash { 0%, 30% { background: color-mix(in oklch, var(--ant-tasks-accent) 26%, transparent); } }
.ant-tasks .ant-tasks-ck {
  --pc: var(--ant-tasks-p4); position: relative; display: grid; place-items: center; width: 19px; height: 19px; margin-top: 1px; border-radius: 50%;
  box-shadow: inset 0 0 0 1.6px var(--pc); background: color-mix(in oklch, var(--pc) 10%, transparent);
  transition: background .25s, scale .35s var(--ant-tasks-spring);
  & svg { width: 13px; height: 13px; stroke-width: 2.6; color: var(--ant-tasks-bg); stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .3s var(--ant-tasks-ease) .05s; }
