  &:active { scale: .82; }
  &[aria-checked="true"] { background: var(--pc); }
  &[aria-checked="true"] svg { stroke-dashoffset: 0; color: var(--ant-tasks-bg); }
  &.p1 { --pc: var(--ant-tasks-p1); } &.p2 { --pc: var(--ant-tasks-p2); } &.p3 { --pc: var(--ant-tasks-p3); }
}
.ant-tasks .ant-tasks-row {
