  &::after { content: ""; position: absolute; inset: 0 0 0 38px; border-radius: 10px; }
  & .tt { position: relative; justify-self: start; max-width: 100%; font-size: 13.5px; font-weight: 520; line-height: 1.35; text-wrap: pretty;
    background: linear-gradient(currentColor, currentColor) no-repeat 0 55% / 0 1.5px; transition: background-size .45s var(--ant-tasks-ease), color .3s; }
  & .meta { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; font-size: 11.5px; color: var(--ant-tasks-faint); font-variant-numeric: tabular-nums; }
  & .meta > span { display: inline-flex; align-items: center; gap: 4px; }
  & .meta svg { width: 12px; height: 12px; }
  & .due { color: var(--ant-tasks-accent); }
  & .due.late { color: var(--ant-tasks-p1); }
  & .due.later { color: var(--ant-tasks-mute); }
  & .pj i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
}
.ant-tasks .ant-tasks-item.is-done .tt, .ant-tasks .ant-tasks-item:has(.ant-tasks-ck[aria-checked="true"]) .tt { background-size: 100% 1.5px; color: var(--ant-tasks-faint); }
.ant-tasks .ant-tasks-empty {
  display: grid; justify-items: center; gap: 8px; padding: 48px 20px; text-align: center; color: var(--ant-tasks-mute);
  & svg { width: 40px; height: 40px; color: var(--ant-tasks-accent); stroke-width: 1.3; }
  & b { font-size: 15px; color: var(--ant-tasks-ink); text-wrap: balance; }
  & p { max-width: 34ch; font-size: 12.5px; text-wrap: pretty; }
}
.ant-tasks .ant-tasks-keys {
  display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 9px 22px; border-top: 1px solid var(--ant-tasks-line); font-size: 11px; color: var(--ant-tasks-faint);
  & span { display: inline-flex; align-items: center; gap: 3px; white-space: nowrap; }
}

/* ── detail ── */
.ant-tasks .ant-tasks-detail {
  grid-area: detail; min-height: 0; overflow-y: auto; scrollbar-width: thin; scrollbar-color: var(--ant-tasks-line2) transparent;
  background: var(--ant-tasks-panel); border-left: 1px solid var(--ant-tasks-line); display: flex; flex-direction: column;
}
.ant-tasks .ant-tasks-dhead { display: flex; align-items: center; gap: 6px; padding: 12px 12px 0 16px; font-size: 11.5px; color: var(--ant-tasks-faint);
  & .crumb { display: inline-flex; align-items: center; gap: 6px; }
  & .crumb i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & .sp { flex: 1; }
}
.ant-tasks .ant-tasks-ib {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--ant-tasks-mute); transition: background .2s, color .2s;
  &:hover { background: var(--ant-tasks-hover); color: var(--ant-tasks-ink); }
  &.danger:hover { color: var(--ant-tasks-p1); background: color-mix(in oklch, var(--ant-tasks-p1) 12%, transparent); }
}
.ant-tasks .ant-tasks-close { display: none; }
.ant-tasks .ant-tasks-dtitle {
  display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 10px; align-items: start; padding: 10px 16px 6px;
  & .ant-tasks-ck { width: 22px; height: 22px; margin-top: 3px; }
  & textarea { width: 100%; resize: none; border: 0; outline: none; background: none; padding: 0; field-sizing: content; min-height: 1.3em;
    font-size: 17px; font-weight: 700; letter-spacing: -.015em; line-height: 1.35; border-radius: 6px; }
  & textarea:focus-visible { box-shadow: 0 0 0 2px var(--ant-tasks-tint); }
}
.ant-tasks .ant-tasks-fld {
  padding: 12px 16px; border-top: 1px solid var(--ant-tasks-line);
