const MODES = { focus: 'Focus', short: 'Short break', long: 'Long break' };
const cfg = { focus: 25, short: 5, long: 15, every: 4, auto: true };
let seq = 0;
const Tk = (name, est, done, o) => Object.assign({ id: 'k' + (++seq), name, est, done, fin: false }, o || {});
let queue = [
  Tk('Write the onboarding copy for Fieldnote', 4, 2),
  Tk('Review Amara’s grant application draft', 2, 0),
  Tk('Fix the export bug in the invoicing script', 3, 0),
  Tk('Sketch the outline for the Lisbon talk', 2, 0),
  Tk('Inbox to zero', 1, 0),
  Tk('Plan the week', 1, 1, { fin: true }),
