/* today's log, minutes since midnight */
const log = [
  { kind: 'focus', s: 520, e: 545, task: 'Plan the week' },
  { kind: 'short', s: 545, e: 550 },
  { kind: 'focus', s: 552, e: 577, task: 'Write the onboarding copy for Fieldnote' },
  { kind: 'short', s: 577, e: 582 },
  { kind: 'focus', s: 585, e: 610, task: 'Write the onboarding copy for Fieldnote' },
  { kind: 'short', s: 610, e: 615 },
