.ant-reader {
  /* re-theme with these four */
  --ant-reader-paper: oklch(0.962 0.02 84);
  --ant-reader-ink: oklch(0.27 0.03 60);
  --ant-reader-accent: oklch(0.47 0.12 255);
  --ant-reader-marker: oklch(0.9 0.14 100);
