  --ant-reader-side: color-mix(in oklch, var(--ant-reader-ink) 5%, var(--ant-reader-paper));
  --ant-reader-sheet: color-mix(in oklch, white 45%, var(--ant-reader-paper));
  --ant-reader-line: color-mix(in oklch, var(--ant-reader-ink) 11%, transparent);
  --ant-reader-line2: color-mix(in oklch, var(--ant-reader-ink) 19%, transparent);
  --ant-reader-hover: color-mix(in oklch, var(--ant-reader-ink) 5.5%, transparent);
  --ant-reader-mute: color-mix(in oklch, var(--ant-reader-ink) 64%, var(--ant-reader-paper));
  --ant-reader-faint: color-mix(in oklch, var(--ant-reader-ink) 44%, var(--ant-reader-paper));
  --ant-reader-tint: color-mix(in oklch, var(--ant-reader-accent) 10%, var(--ant-reader-sheet));
  --ant-reader-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --ant-reader-ease: cubic-bezier(.2, .8, .2, 1);
  --ant-reader-spring: linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ant-reader-h, 680px); box-sizing: border-box; container-type: inline-size; overflow: clip; isolation: isolate;
  border-radius: 14px; background: var(--ant-reader-paper); color: var(--ant-reader-ink); color-scheme: light; accent-color: var(--ant-reader-accent);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--ant-reader-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ant-reader-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
