  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-block; min-width: 16px; padding: 2px 4px; border-radius: 4px; text-align: center; font: 600 10px/1.2 ui-monospace, Menlo, monospace; color: var(--ant-reader-faint); box-shadow: inset 0 0 0 1px var(--ant-reader-line2); }
}
.ant-reader .ant-reader-app { height: 100%; display: grid; grid-template-columns: 196px 318px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "side list read"; }

/* side */
.ant-reader .ant-reader-side { grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 18px; padding: 18px 12px 14px; background: var(--ant-reader-side); border-right: 1px solid var(--ant-reader-line); }
