@property --ant-journal-mc { syntax: "<color>"; inherits: true; initial-value: oklch(0.84 0.12 115); }
.ant-journal {
  /* re-theme with these four (mood colours live in the scale below) */
  --ant-journal-bg: oklch(0.982 0.006 85);
  --ant-journal-ink: oklch(0.25 0.015 50);
  --ant-journal-card: oklch(0.997 0.002 85);
  --ant-journal-accent: oklch(0.52 0.1 160);
  /* mood scale, 1 → 5 */
  --ant-journal-m1: oklch(0.64 0.085 265);
  --ant-journal-m2: oklch(0.74 0.075 228);
  --ant-journal-m3: oklch(0.84 0.055 165);
  --ant-journal-m4: oklch(0.86 0.12 118);
  --ant-journal-m5: oklch(0.83 0.14 78);
  /* derived */
  --ant-journal-line: color-mix(in oklch, var(--ant-journal-ink) 10%, transparent);
  --ant-journal-line2: color-mix(in oklch, var(--ant-journal-ink) 18%, transparent);
  --ant-journal-hover: color-mix(in oklch, var(--ant-journal-ink) 5%, transparent);
  --ant-journal-mute: color-mix(in oklch, var(--ant-journal-ink) 62%, var(--ant-journal-bg));
  --ant-journal-faint: color-mix(in oklch, var(--ant-journal-ink) 40%, var(--ant-journal-bg));
  --ant-journal-mc: var(--ant-journal-m4);
  --ant-journal-ease: cubic-bezier(.2, .8, .2, 1);
  --ant-journal-spring: linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ant-journal-h, 680px); box-sizing: border-box; container-type: inline-size; overflow: clip; isolation: isolate;
  display: flex; flex-direction: column; border-radius: 18px; background: var(--ant-journal-bg); color: var(--ant-journal-ink); color-scheme: light; accent-color: var(--ant-journal-accent);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--ant-journal-line); -webkit-tap-highlight-color: transparent;
  transition: --ant-journal-mc .8s var(--ant-journal-ease);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ant-journal-ink); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & h2, & h3, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-block; min-width: 16px; padding: 2px 4px; border-radius: 4px; text-align: center; font: 600 10px/1.2 ui-monospace, Menlo, monospace; color: var(--ant-journal-faint); background: var(--ant-journal-card); box-shadow: inset 0 0 0 1px var(--ant-journal-line2); }
  & h3 { font-size: 10.5px; font-weight: 720; letter-spacing: .1em; text-transform: uppercase; color: var(--ant-journal-faint); }
}
