  & .ln { fill: none; stroke: var(--ant-journal-ink); stroke-width: 1.6; vector-effect: non-scaling-stroke; }
  & .ar { fill: color-mix(in oklch, var(--ant-journal-mc) 35%, transparent); stroke: none; }
  & .dot { fill: var(--ant-journal-ink); }
  & .mid { stroke: var(--ant-journal-line2); stroke-dasharray: 2 3; vector-effect: non-scaling-stroke; }
}
.ant-journal .ant-journal-spark.draw svg { animation: ant-journal-wipe 1.2s var(--ant-journal-ease) both; }
@keyframes ant-journal-wipe { from { clip-path: inset(-4px 100% -4px 0); } to { clip-path: inset(-4px 0 -4px 0); } }
.ant-journal .ant-journal-lift {
  display: grid; gap: 2px; position: relative;
  & li { display: grid; grid-template-columns: 92px 1fr 40px; align-items: center; gap: 8px; height: 26px; font-size: 12px; }
  & li span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--ant-journal-mute); }
  & li.me span { color: var(--ant-journal-ink); font-weight: 650; }
  & .track { position: relative; height: 12px; }
  & .track::before { content: ""; position: absolute; left: 50%; top: -3px; bottom: -3px; width: 1px; background: var(--ant-journal-line2); }
  & .track i { position: absolute; top: 1px; bottom: 1px; border-radius: 3px; transition: left .6s var(--ant-journal-spring), width .6s var(--ant-journal-spring), background .4s; }
  & .track i.up { left: 50%; width: var(--w); background: var(--ant-journal-m5); }
  & .track i.down { left: calc(50% - var(--w)); width: var(--w); background: var(--ant-journal-m1); }
  & output { text-align: right; font-size: 11.5px; font-weight: 650; font-variant-numeric: tabular-nums; }
}
.ant-journal .ant-journal-note { font-size: 12px; color: var(--ant-journal-mute); text-wrap: pretty; & b { color: var(--ant-journal-ink); } }
.ant-journal .ant-journal-toast {
  position: absolute; z-index: 60; left: 50%; bottom: 18px; translate: -50% 0; max-width: calc(100% - 32px); padding: 9px 14px; border-radius: 12px;
  background: var(--ant-journal-ink); color: var(--ant-journal-bg); font-size: 12.5px; font-weight: 600; box-shadow: 0 16px 34px -14px var(--ant-journal-ink);
  transition: translate .5s var(--ant-journal-spring), opacity .2s; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  @starting-style { translate: -50% 16px; opacity: 0; }
}

@container (width < 1080px) { .ant-journal .ant-journal-app { grid-template-columns: 264px minmax(0, 1fr) 270px; } }
@container (width < 960px) {
  .ant-journal .ant-journal-app { grid-template-columns: 270px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "cal entry" "ins entry"; }
  .ant-journal .ant-journal-entry { grid-row: 1 / -1; }
  .ant-journal .ant-journal-cal { overflow: visible; padding-bottom: 6px; }
  .ant-journal .ant-journal-ins { border-left: 0; border-right: 1px solid var(--ant-journal-line); border-top: 1px solid var(--ant-journal-line); gap: 16px; }
  .ant-journal .ant-journal-keys, .ant-journal .ant-journal-legend { display: none; }
}
@container (width < 760px) {
  .ant-journal .ant-journal-tabs {
    display: flex; gap: 2px; margin: 10px 12px 0; padding: 3px; border-radius: 11px; background: var(--ant-journal-hover);
    & button { flex: 1; height: 30px; border-radius: 8px; font-size: 12.5px; font-weight: 620; color: var(--ant-journal-mute); transition: background .25s, color .25s; }
    & button[aria-selected="true"] { background: var(--ant-journal-card); color: var(--ant-journal-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--ant-journal-ink) 18%, transparent); }
  }
  .ant-journal .ant-journal-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .ant-journal .ant-journal-cal, .ant-journal .ant-journal-entry, .ant-journal .ant-journal-ins { grid-area: main; border: 0; display: none; }
  .ant-journal[data-tab="cal"] .ant-journal-cal { display: block; }
  .ant-journal[data-tab="entry"] .ant-journal-entry { display: block; }
  .ant-journal[data-tab="ins"] .ant-journal-ins { display: flex; background: none; }
  .ant-journal .ant-journal-moods button { padding: 8px 2px 6px; font-size: 10.5px; }
  .ant-journal .ant-journal-moods svg { width: 28px; height: 28px; }
}

@media (prefers-reduced-motion: reduce) {
  .ant-journal { transition: none; }
  .ant-journal *, .ant-journal *::before, .ant-journal *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important; }
  .ant-journal .ant-journal-spark.draw svg { animation: none; }
}

