/* ── Daybook · daily journal with mood ────────────────────────────────
   Two months of entries are generated from a seeded PRNG in which each
   activity nudges the mood, so the "what lifts you" panel has something
   real to find. Changing today's mood or tags recomputes every average and
   difference, and the ranked bars FLIP into their new order. The selected
   day's mood colour is a registered <color> property, so the whole entry
   header eases from one mood to the next. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const DAY = 864e5, D = (y, m, d) => Math.round(Date.UTC(y, m - 1, d) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const dow = n => ((n + 4) % 7 + 7) % 7;
const TODAY = D(2026, 10, 2), FIRST = D(2026, 8, 3), LASTCELL = D(2026, 10, 4);
const WDL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONL = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const MOODS = ['', 'Awful', 'Low', 'Okay', 'Good', 'Great'];
const MOUTH = ['', 'M8 16.6Q12 12.6 16 16.6', 'M8.4 15.9Q12 14 15.6 15.9', 'M8.5 15.2h7', 'M8.4 14.2Q12 16.8 15.6 14.2', 'M7.8 13.6Q12 19 16.2 13.6Z'];
const face = n => '<svg viewBox="0 0 24 24" aria-hidden="true"><circle class="f" cx="12" cy="12" r="9.2"/><circle cx="12" cy="12" r="9.2"/><path d="M9 9.6v.6M15 9.6v.6" stroke-width="2.2"/><path d="' + MOUTH[n] + '"' + (n === 5 ? ' fill="currentColor" fill-opacity=".14"' : '') + '/></svg>';
const TI = {
  sleep: '<path d="M19 14.5A7.5 7.5 0 0 1 9.5 5a7.5 7.5 0 1 0 9.5 9.5Z"/>',
  move: '<circle cx="14" cy="5" r="1.6"/><path d="m8 21 3-6 3 2v4M7 11l3-3h4l2 4 3 1M11 15l-1-4"/>',
  out: '<path d="M12 3v2M12 19v2M4.6 4.6 6 6M18 18l1.4 1.4M3 12h2M19 12h2M4.6 19.4 6 18M18 6l1.4-1.4"/><circle cx="12" cy="12" r="4"/>',
  friends: '<circle cx="9" cy="8.5" r="3"/><path d="M3.5 19a5.5 5.5 0 0 1 11 0"/><path d="M15.5 5.6a3 3 0 0 1 0 5.8M17 14.2a5.5 5.5 0 0 1 3.5 4.8"/>',
  deep: '<rect x="4" y="5" width="16" height="11" rx="1.5"/><path d="M9 20h6M12 16v4"/>',
  coffee: '<path d="M5 9h11v5a5 5 0 0 1-5 5h-1a5 5 0 0 1-5-5Z"/><path d="M16 10h1.5a2.5 2.5 0 0 1 0 5H16M8 3.5v2.5M11 3.5v2.5"/>',
  screens: '<rect x="7" y="3" width="10" height="18" rx="2"/><path d="M11 18h2"/>',
  alcohol: '<path d="M7 3h10l-1 7a4 4 0 0 1-8 0Z"/><path d="M12 14v6M9 20.5h6"/>',
};
const TAGS = [
  { id: 'sleep', name: 'Slept 7h+', eff: .7, p: .6 },
  { id: 'move', name: 'Exercise', eff: .6, p: .45 },
  { id: 'out', name: 'Outside', eff: .45, p: .55 },
  { id: 'friends', name: 'Friends', eff: .5, p: .32 },
  { id: 'deep', name: 'Deep work', eff: .35, p: .5 },
  { id: 'coffee', name: 'Late coffee', eff: -.6, p: .3 },
  { id: 'screens', name: 'Screens in bed', eff: -.45, p: .42 },
  { id: 'alcohol', name: 'Alcohol', eff: -.4, p: .2 },
];
const TN = Object.fromEntries(TAGS.map(t => [t.id, t]));
const ticon = id => '<svg viewBox="0 0 24 24" aria-hidden="true">' + TI[id] + '</svg>';
const PROMPTS = ['What made today feel the way it did?', 'What surprised you today?', 'What would you tell yourself this morning?', 'Where did your energy go?', 'What are you looking forward to?', 'What did you let go of today?', 'Who made a difference today, and how?', 'What would make tomorrow a 5?'];
const POOL = ['',
  ['Slept badly and everything felt heavy. Cancelled the gym and stayed in.', 'Rough one. The deadline moved forward and I snapped at Ruth. I owe her an apology.', 'Could not shake a headache. Lay on the floor with the cat for an hour.'],
  ['Grey and slow. Got through the inbox but not much else.', 'Tired all afternoon. Early night, phone in the other room.', 'Too much coffee, too little lunch. Noted.'],
  ['Ordinary day. Work was fine, dinner was fine, the rain stopped around six.', 'Half good, half tired. The morning swim helped more than I expected.', 'Nothing special, which is its own kind of nice.'],
  ['Good focus in the morning, long walk after lunch. Called Mum.', 'Cooked the new dal recipe and it actually worked.', 'Finished the chapter I had been stuck on for a week.'],
  ['Cycled to the coast with Priya and Tom. Sunburnt, happy, starving.', 'Everything clicked at work, then a long dinner with friends. More days like this.', 'Swam in the lake at seven. Cold, perfect, still grinning at lunch.'],
];
/* seeded generation */
function rng(a) { return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const R = rng(16);
const E = new Map();
for (let n = FIRST; n < TODAY; n++) {
  if (R() < .08) continue;
  const we = dow(n) === 0 || dow(n) === 6, tags = new Set();
  TAGS.forEach(t => { let p = t.p; if (we && (t.id === 'friends' || t.id === 'out')) p += .25; if (we && t.id === 'deep') p -= .35; if (R() < p) tags.add(t.id); });
  let m = 2.3 + (we ? .25 : 0) + (R() - .5) * 2.4;
  tags.forEach(id => { m += TN[id].eff; });
  const mood = Math.max(1, Math.min(5, Math.round(m)));
  const pool = POOL[mood];
  E.set(n, { mood, tags, text: R() < .8 ? pool[Math.floor(R() * pool.length)] : '', grat: R() < .4 ? ['A proper lunch break', '', ''] : ['', '', ''] });
}
E.set(TODAY, { mood: 4, tags: new Set(['sleep', 'deep', 'coffee']), grat: ['Sam’s terrible puns', 'The canal at dusk', ''],
  text: 'Finished the first full draft of the onboarding copy before lunch, which felt like putting down a heavy bag. Late coffee with Sam at four, the mistake I make every Friday. Walked home the long way along the canal.' });
const S = { sel: TODAY, prompt: 0, tab: 'entry', drawn: false };

/* ── maths ── */
const withMood = () => [...E.entries()].filter(([, e]) => e.mood);
function stats() {
  const all = withMood(), avg = all.reduce((n, [, e]) => n + e.mood, 0) / (all.length || 1);
  const lift = TAGS.map(t => {
    const w = all.filter(([, e]) => e.tags.has(t.id)), wo = all.filter(([, e]) => !e.tags.has(t.id));
    const a = w.reduce((n, [, e]) => n + e.mood, 0) / (w.length || 1), b = wo.reduce((n, [, e]) => n + e.mood, 0) / (wo.length || 1);
    return { id: t.id, name: t.name, d: w.length && wo.length ? a - b : 0, n: w.length, a };
  }).sort((x, y) => y.d - x.d);
  const wd = Array.from({ length: 7 }, (_, k) => { const L = all.filter(([n]) => dow(n) === k); return { k, avg: L.reduce((s, [, e]) => s + e.mood, 0) / (L.length || 1), n: L.length }; });
  return { all, avg, lift, wd };
}
function streak() { let n = TODAY, k = 0; while (E.has(n)) { k++; n--; } return k; }
const fmt1 = v => (Math.round(v * 10) / 10).toFixed(1);
const longDay = n => { const [, m, d] = ymd(n); return WDL[dow(n)] + ' ' + d + ' ' + MONL[m]; };
function relDay(n) { const k = TODAY - n; return k === 0 ? 'Today' : k === 1 ? 'Yesterday' : k < 7 ? k + ' days ago' : Math.floor(k / 7) + (k < 14 ? ' week ago' : ' weeks ago'); }

/* ── calendar ── */
function renderCal(anim) {
  const MS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  let h = '';
  for (let w = FIRST, i = 0; w <= LASTCELL; w += 7) {
    const firstOfMonth = [0, 1, 2, 3, 4, 5, 6].map(k => w + k).find(n => ymd(n)[2] === 1);
    h += '<div role="row"><span class="ml" role="rowheader">' + (w === FIRST ? MS[ymd(w)[1]] : firstOfMonth != null ? MS[ymd(firstOfMonth)[1]] : '') + '</span>';
    for (let k = 0; k < 7; k++) {
      const n = w + k, e = E.get(n), fut = n > TODAY, d = ymd(n)[2];
      const cls = (e && e.mood ? 'has m' + e.mood : e ? 'has' : fut ? '' : 'empty') + (n === TODAY ? ' today' : '') + (d === 1 ? ' first' : '');
      const lbl = longDay(n) + (e && e.mood ? ', ' + MOODS[e.mood] : e ? ', no mood yet' : fut ? '' : ', no entry');
      h += '<span role="gridcell"><button type="button" class="' + cls + '" data-day="' + n + '" style="--i:' + (i++) + '" aria-label="' + lbl + '" aria-selected="' + (n === S.sel) + '" tabindex="' + (n === S.sel ? 0 : -1) + '"' + (fut ? ' aria-disabled="true" title="That day has not happened yet"' : '') + '>' + d + '</button></span>';
    }
    h += '</div>';
  }
  const g = $('[data-grid]');
  g.innerHTML = h;
  if (anim === false || RM.matches) $$('button', g).forEach(b => b.style.animation = 'none');
  $('[data-mtitle]').textContent = 'Since 3 August';
  const all = withMood(), avg = all.reduce((s2, [, e]) => s2 + e.mood, 0) / (all.length || 1), span = TODAY - FIRST + 1;
  $('[data-msum]').innerHTML = '<b>' + E.size + '</b> of ' + span + ' days written · average <b>' + fmt1(avg) + '</b> (' + MOODS[Math.round(avg)].toLowerCase() + ')';
  $('[data-streak]').textContent = streak() + '-day streak';
}
function renderLegend() { $('[data-legend]').innerHTML = '<span>Awful</span>' + [1, 2, 3, 4, 5].map(k => '<i style="background:var(--ant-journal-m' + k + ')"></i>').join('') + '<span>Great</span>'; }

/* ── entry ── */
function setMc(e) { root.style.setProperty('--ant-journal-mc', e && e.mood ? 'var(--ant-journal-m' + e.mood + ')' : 'var(--ant-journal-line2)'); }
function renderEntry(fade) {
  const n = S.sel, e = E.get(n), box = $('[data-entry]');
  setMc(e);
  const head = '<header class="ant-journal-ehead"><div class="nav"><span class="rel">' + relDay(n) + '</span>' +
    '<button type="button" class="ant-journal-ib" data-step="-1" aria-label="Previous day"' + (n <= FIRST ? ' disabled title="This is your first day"' : '') + '><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button>' +
    '<button type="button" class="ant-journal-ib" data-step="1" aria-label="Next day"' + (n >= TODAY ? ' disabled title="Tomorrow has not happened yet"' : '') + '><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg></button></div>' +
    '<h2>' + longDay(n) + '</h2>' + (e ? '<p class="saved" data-saved><i></i>' + (n === TODAY ? 'Saved 10:24' : 'Saved') + '</p>' : '') + '</header>';
  if (!e) {
    box.innerHTML = head + '<div class="ant-journal-none"><b>No entry for ' + WDL[dow(n)] + '</b><p>Missed days happen. You can still write one; most people remember more than they expect.</p><button type="button" data-act="create">Write this entry</button></div>';
  } else {
    const words = (e.text.match(/\S+/g) || []).length;
    box.innerHTML = head + '<div class="ant-journal-body">' +
      '<section class="ant-journal-sec"><header><h3>Mood</h3></header><div class="ant-journal-moods" role="radiogroup" aria-label="Mood">' +
      [1, 2, 3, 4, 5].map(k => '<button type="button" role="radio" data-mood="' + k + '" style="--c:var(--ant-journal-m' + k + ')" aria-checked="' + (e.mood === k) + '" tabindex="' + ((e.mood || 3) === k ? 0 : -1) + '">' + face(k) + MOODS[k] + '</button>').join('') + '</div></section>' +
      '<section class="ant-journal-sec"><header><h3>What shaped the day</h3></header><div class="ant-journal-tagset">' +
      TAGS.map(t => '<button type="button" data-tag="' + t.id + '" aria-pressed="' + e.tags.has(t.id) + '">' + ticon(t.id) + t.name + '</button>').join('') + '</div></section>' +
      '<section class="ant-journal-sec"><div class="ant-journal-prompt"><span data-prompt>' + promptFor() + '</span><button type="button" class="ant-journal-shuffle" data-act="prompt" aria-label="Another prompt"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h3.5c3 0 4.5 2 6 5s3 5 6 5H20M4 17h3.5c1.4 0 2.5-.5 3.4-1.3M13.1 8.3c.9-.8 2-1.3 3.4-1.3H20M17.5 4.5 20 7l-2.5 2.5M17.5 14.5 20 17l-2.5 2.5"/></svg>Another</button></div>' +
      '<textarea class="ant-journal-text" data-text aria-label="Journal entry" placeholder="Write as much or as little as you like.">' + esc(e.text) + '</textarea><p class="ant-journal-wc" data-wc>' + words + (words === 1 ? ' word' : ' words') + '</p></section>' +
      '<section class="ant-journal-sec"><header><h3>Three good things</h3></header><div class="ant-journal-grat">' +
      e.grat.map((g, i) => '<label><input data-grat="' + i + '" value="' + esc(g) + '" placeholder="' + ['Something small that went right', 'Someone you are glad of', 'Anything at all'][i] + '" aria-label="Good thing ' + (i + 1) + '"></label>').join('') + '</div></section></div>';
  }
  if (fade && !RM.matches) box.animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.2,.8,.2,1)' });
}

const promptFor = () => S.sel === TODAY ? PROMPTS[S.prompt] : PROMPTS[S.prompt].replace(/today/g, 'that day').replace('this morning', 'that morning').replace('tomorrow', 'the next day');
/* ── insights ── */
function renderIns() {
  const st = stats(), box = $('[data-ins]');
  const first = new Map($$('.ant-journal-lift li', box).map(li => [li.dataset.t, li.getBoundingClientRect().top]));
  const inMonth = st.all.filter(([n]) => n > TODAY - 30), cnt = [0, 0, 0, 0, 0, 0];
  inMonth.forEach(([, e]) => cnt[e.mood]++);
  const mAvg = inMonth.reduce((s, [, e]) => s + e.mood, 0) / (inMonth.length || 1);
  // sparkline: last 30 days
  const pts = []; for (let k = 29; k >= 0; k--) { const e = E.get(TODAY - k); if (e && e.mood) pts.push([29 - k, e.mood]); }
  const X = i => (i / 29 * 100).toFixed(2), Y = v => (60 - (v - 1) / 4 * 54).toFixed(2);
  const line = pts.map((p, i) => (i ? 'L' : 'M') + X(p[0]) + ' ' + Y(p[1])).join('');
  const area = pts.length ? line + 'L' + X(pts[pts.length - 1][0]) + ' 62L' + X(pts[0][0]) + ' 62Z' : '';
  const best = st.wd.filter(w => w.n).sort((a, b) => b.avg - a.avg)[0];
  const max = Math.max(.6, ...st.lift.map(l => Math.abs(l.d)));
  const today = E.get(TODAY);
  box.innerHTML =
    '<section class="ant-journal-avg"><h3>Last 30 days</h3><div class="big"><b>' + (inMonth.length ? fmt1(mAvg) : '–') + '</b><span>average of ' + inMonth.length + (inMonth.length === 1 ? ' day' : ' days') + '</span></div>' +
    '<div class="dist">' + [1, 2, 3, 4, 5].map(k => '<i style="--n:' + cnt[k] + ';--c:var(--ant-journal-m' + k + ')" title="' + MOODS[k] + ': ' + cnt[k] + '"></i>').join('') + '</div>' +
    '<div class="dl">' + [1, 2, 3, 4, 5].map(k => '<span>' + MOODS[k] + ' ' + cnt[k] + '</span>').join('') + '</div></section>' +
    '<section><div class="ant-journal-spark' + (S.drawn ? '' : ' draw') + '"><svg viewBox="0 0 100 62" preserveAspectRatio="none" aria-label="Mood over the last 30 days"><line class="mid" x1="0" x2="100" y1="' + Y(3) + '" y2="' + Y(3) + '"/><path class="ar" d="' + area + '"/><path class="ln" d="' + line + '"/></svg></div></section>' +
    '<section><h3>What lifts you</h3><p class="ant-journal-note" style="margin:6px 0 8px">Average mood on days with each activity, minus days without. ' + st.all.length + ' days of entries.</p><ol class="ant-journal-lift">' +
    st.lift.map(l => '<li data-t="' + l.id + '" class="' + (today && today.tags.has(l.id) ? 'me' : '') + '" title="' + l.name + ': ' + l.n + ' days, average ' + fmt1(l.a) + '"><span>' + l.name + '</span><div class="track"><i class="' + (l.d >= 0 ? 'up' : 'down') + '" style="--w:' + (Math.abs(l.d) / max * 50).toFixed(1) + '%"></i></div><output>' + (Math.abs(l.d) < .05 ? '' : l.d > 0 ? '+' : '−') + fmt1(Math.abs(l.d)) + '</output></li>').join('') + '</ol></section>' +
    (best ? '<p class="ant-journal-note">Your best day of the week is <b>' + WDL[best.k] + '</b>, averaging <b>' + fmt1(best.avg) + '</b> over ' + best.n + ' entries.</p>' : '');
  S.drawn = true;
  if (!RM.matches && first.size) $$('.ant-journal-lift li', box).forEach(li => { const t = first.get(li.dataset.t); if (t == null) return; const dy = t - li.getBoundingClientRect().top; if (Math.abs(dy) > 1) li.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 600, easing: SPRING }); });
}

/* ── actions ── */
let tt = 0;
function toast(msg) { const t = $('[data-toast]'); $('[data-tmsg]').textContent = msg; t.hidden = false; clearTimeout(tt); tt = setTimeout(() => { t.hidden = true; }, 2600); }
function select(n, focusCal) {
  if (n > TODAY || n < FIRST) return;
  S.sel = n;
  renderCal(false); renderEntry(true);
  if (focusCal) { const b = $('[data-grid] [data-day="' + n + '"]'); if (b) b.focus({ preventScroll: true }); }
}
let saveT = 0;
function saving() {
  const s = $('[data-saved]'); if (!s) return;
  s.classList.add('busy'); s.lastChild.textContent = 'Saving…';
  clearTimeout(saveT); saveT = setTimeout(() => { if (!root.isConnected) return; const x = $('[data-saved]'); if (x) { x.classList.remove('busy'); x.lastChild.textContent = 'Saved just now'; } }, 700);
}
function setMood(k) {
  const e = E.get(S.sel); if (!e) return;
  e.mood = k; setMc(e);
  $$('[data-mood]').forEach(b => { const on = +b.dataset.mood === k; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
  renderCal(false); renderIns(); saving();
}

root.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b || !root.contains(b)) return;
  const d = b.dataset;
  if (b.getAttribute('aria-disabled') === 'true') return toast(b.title);
  if (d.tab && b.closest('[data-tabs]')) { root.dataset.tab = d.tab; $$('[data-tabs] [role=tab]').forEach(x => x.setAttribute('aria-selected', x === b)); return; }
  if (d.day) { select(+d.day); if (root.dataset.tab === 'cal' && b.closest('[data-grid]')) { /* narrow: jump to the entry */ root.dataset.tab = 'entry'; $$('[data-tabs] [role=tab]').forEach(x => x.setAttribute('aria-selected', x.dataset.tab === 'entry')); } return; }
  if (d.step) return select(S.sel + +d.step);
  if (d.mood) return setMood(+d.mood);
  if (d.tag) { const en = E.get(S.sel); en.tags.has(d.tag) ? en.tags.delete(d.tag) : en.tags.add(d.tag); b.setAttribute('aria-pressed', en.tags.has(d.tag)); renderIns(); saving(); return; }
  if (d.act === 'prompt') { S.prompt = (S.prompt + 1) % PROMPTS.length; const p = $('[data-prompt]'); p.textContent = promptFor(); if (!RM.matches) p.animate([{ opacity: 0, transform: 'translateY(4px)' }, { opacity: 1, transform: 'none' }], { duration: 300, easing: 'ease-out' }); return; }
  if (d.act === 'create') { E.set(S.sel, { mood: null, tags: new Set(), text: '', grat: ['', '', ''] }); renderEntry(true); renderCal(false); const r = $('[data-mood="3"]'); if (r) r.focus(); return toast('New entry for ' + longDay(S.sel)); }
});
root.addEventListener('input', e => {
  const t = e.target, en = E.get(S.sel); if (!en) return;
  if (t.matches('[data-text]')) { en.text = t.value; const w = (t.value.match(/\S+/g) || []).length; $('[data-wc]').textContent = w + (w === 1 ? ' word' : ' words'); saving(); }
  if (t.matches('[data-grat]')) { en.grat[+t.dataset.grat] = t.value; saving(); }
});
root.addEventListener('keydown', e => {
  const t = e.target, k = e.key;
  if (t.closest && t.closest('[data-grid]') && t.dataset.day && /^Arrow/.test(k)) {
    e.preventDefault();
    const n = +t.dataset.day + ({ ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 })[k];
    if (n <= TODAY && n >= FIRST) select(n, true);
    return;
  }
  if (t.closest && t.closest('[role=radiogroup]') && /^Arrow/.test(k)) {
    e.preventDefault(); const cur = +t.dataset.mood || 3, nx = Math.max(1, Math.min(5, cur + (k === 'ArrowRight' || k === 'ArrowDown' ? 1 : -1)));
    setMood(nx); $('[data-mood="' + nx + '"]').focus(); return;
  }
  if (t.matches('input, textarea') || e.metaKey || e.ctrlKey || e.altKey) return;
  if (k === 'ArrowLeft' || k === 'ArrowRight') { e.preventDefault(); return select(S.sel + (k === 'ArrowLeft' ? -1 : 1)); }
  if (/^[1-5]$/.test(k) && E.get(S.sel)) { e.preventDefault(); return setMood(+k); }
  if (k === 't' || k === 'T') { e.preventDefault(); return select(TODAY, true); }
});

renderLegend();
renderCal(true);
renderEntry(false);
renderIns();

