.ant-outline {
  /* re-theme with these four */
  --ant-outline-bg: oklch(0.175 0.006 120);
  --ant-outline-ink: oklch(0.93 0.012 110);
  --ant-outline-accent: oklch(0.9 0.19 124);
  --ant-outline-panel: oklch(0.205 0.008 120);
  /* derived */
  --ant-outline-line: color-mix(in oklch, var(--ant-outline-ink) 8%, transparent);
  --ant-outline-line2: color-mix(in oklch, var(--ant-outline-ink) 15%, transparent);
  --ant-outline-hover: color-mix(in oklch, var(--ant-outline-ink) 5%, transparent);
  --ant-outline-mute: color-mix(in oklch, var(--ant-outline-ink) 62%, var(--ant-outline-bg));
  --ant-outline-faint: color-mix(in oklch, var(--ant-outline-ink) 36%, var(--ant-outline-bg));
  --ant-outline-tint: color-mix(in oklch, var(--ant-outline-accent) 13%, transparent);
  --ant-outline-on: oklch(0.2 0.04 125);
  --ant-outline-ease: cubic-bezier(.2, .8, .2, 1);
  --ant-outline-spring: linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ant-outline-h, 680px); box-sizing: border-box; container-type: inline-size; overflow: clip; isolation: isolate;
  border-radius: 16px; background: var(--ant-outline-bg); color: var(--ant-outline-ink); color-scheme: dark; accent-color: var(--ant-outline-accent);
  font: 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ant-outline-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .35; }
  & h3, & p, & ul, & dl, & dd { margin: 0; padding: 0; }
  & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-block; min-width: 16px; padding: 2px 4px; border-radius: 4px; text-align: center; font: 600 10px/1.2 ui-monospace, Menlo, monospace; color: var(--ant-outline-mute); box-shadow: inset 0 0 0 1px var(--ant-outline-line2); }
  & mark { background: color-mix(in oklch, var(--ant-outline-accent) 35%, transparent); color: inherit; border-radius: 3px; }
  & h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--ant-outline-faint); }
}
.ant-outline .ant-outline-app { height: 100%; display: grid; grid-template-columns: 236px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "side main"; }

.ant-outline .ant-outline-side { grid-area: side; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 10px; padding: 18px 12px 14px; background: var(--ant-outline-panel); border-right: 1px solid var(--ant-outline-line); }
.ant-outline .ant-outline-brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 12px;
  & svg { width: 26px; height: 26px; color: var(--ant-outline-accent); stroke-width: 1.6; }
  & span { display: grid; line-height: 1.2; }
  & b { font-size: 15px; font-weight: 780; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--ant-outline-faint); }
}
.ant-outline .ant-outline-side > h3 { padding: 0 8px; }
.ant-outline .ant-outline-docs {
  display: grid; gap: 1px;
  & button { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 9px; padding: 7px 8px; border-radius: 8px; text-align: left; font-size: 13px; font-weight: 540; color: var(--ant-outline-mute); transition: background .2s, color .2s; }
  & button i { width: 7px; height: 7px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px currentColor; }
  & button output { font: 11px ui-monospace, Menlo, monospace; color: var(--ant-outline-faint); font-variant-numeric: tabular-nums; }
  & button:hover { background: var(--ant-outline-hover); color: var(--ant-outline-ink); }
  & button[aria-current="true"] { background: var(--ant-outline-tint); color: var(--ant-outline-ink); font-weight: 650; }
  & button[aria-current="true"] i { background: var(--ant-outline-accent); box-shadow: none; }
}
.ant-outline .ant-outline-cheat {
  margin-top: auto; padding: 12px 10px 8px; border-radius: 12px; background: var(--ant-outline-hover);
  & h3 { margin-bottom: 6px; }
  & dl > div { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 3.5px 0; font-size: 11.5px; color: var(--ant-outline-mute); }
  & dt { display: flex; gap: 3px; }
}

/* main */
.ant-outline .ant-outline-main { grid-area: main; min-height: 0; min-width: 0; display: flex; flex-direction: column; }
.ant-outline .ant-outline-top { display: flex; align-items: center; gap: 8px; padding: 12px 16px 6px 22px; }
.ant-outline .ant-outline-top .ant-outline-drawerbtn { display: none; }
.ant-outline .ant-outline-ib { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--ant-outline-mute); flex: none; &:hover { background: var(--ant-outline-hover); color: var(--ant-outline-ink); } }
.ant-outline .ant-outline-crumbs {
  flex: 1; min-width: 0; display: flex; align-items: center; gap: 2px; overflow: hidden; white-space: nowrap; font-size: 12.5px; color: var(--ant-outline-faint);
  & button { max-width: 22ch; overflow: hidden; text-overflow: ellipsis; padding: 4px 7px; border-radius: 6px; color: var(--ant-outline-mute); font-weight: 560; flex: none; }
  & button:hover { background: var(--ant-outline-hover); color: var(--ant-outline-ink); }
  & .sep { color: var(--ant-outline-faint); flex: none; }
  & .sep svg { width: 12px; height: 12px; }
  & [aria-current] { padding: 4px 7px; color: var(--ant-outline-ink); font-weight: 650; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
}
.ant-outline .ant-outline-find {
  display: flex; align-items: center; gap: 7px; width: clamp(150px, 22cqi, 240px); height: 32px; padding: 0 10px; border-radius: 9px; background: var(--ant-outline-hover); cursor: text;
  box-shadow: inset 0 0 0 1px var(--ant-outline-line); transition: box-shadow .2s;
  & svg { color: var(--ant-outline-faint); }
  & input { flex: 1; min-width: 0; height: 100%; border: 0; outline: none; background: none; font-size: 12.5px; }
  & input::placeholder { color: var(--ant-outline-faint); }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--ant-outline-accent); }
}
.ant-outline .ant-outline-tools {
  display: flex; align-items: center; gap: 2px; padding: 0 16px 8px 18px; border-bottom: 1px solid var(--ant-outline-line);
  & button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 9px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--ant-outline-mute); transition: background .2s, color .2s; }
  & button svg { width: 15px; height: 15px; }
  & button:hover:not(:disabled) { background: var(--ant-outline-hover); color: var(--ant-outline-ink); }
  & button[aria-checked="true"] { color: var(--ant-outline-on); background: var(--ant-outline-accent); }
  & i { width: 1px; height: 16px; margin: 0 6px; background: var(--ant-outline-line2); }
}
.ant-outline .ant-outline-scroll { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--ant-outline-line2) transparent; }
.ant-outline .ant-outline-doc { max-width: 760px; margin: 0 auto; padding: 22px clamp(18px, 4cqi, 48px) 60px; }
.ant-outline .ant-outline-title {
  margin: 0 0 14px 30px; font-size: clamp(22px, 2.5cqi, 30px); font-weight: 760; letter-spacing: -.03em; line-height: 1.15; text-wrap: balance; transform-origin: left top;
  & .t { outline: none; border-radius: 6px; }
  & .t:focus-visible { box-shadow: 0 0 0 2px var(--ant-outline-tint); outline: none; }
  & small { display: block; margin-top: 6px; font-size: 12px; font-weight: 500; letter-spacing: 0; color: var(--ant-outline-faint); font-variant-numeric: tabular-nums; }
}
.ant-outline .ant-outline-tree, .ant-outline .ant-outline-tree ul { display: grid; }
.ant-outline .ant-outline-tree ul { position: relative; margin-left: 30px; padding-left: 0; }
.ant-outline .ant-outline-tree ul::before { content: ""; position: absolute; left: -15px; top: 2px; bottom: 6px; width: 1px; background: var(--ant-outline-line2); transition: background .2s; }
.ant-outline .ant-outline-tree li:has(> .row:hover) > ul::before, .ant-outline .ant-outline-tree li:has(> .row:focus-within) > ul::before { background: color-mix(in oklch, var(--ant-outline-accent) 55%, transparent); }
.ant-outline .ant-outline-tree .row {
  position: relative; display: grid; grid-template-columns: 20px 22px minmax(0, 1fr); align-items: start; min-height: 30px; margin-left: -12px; border-radius: 7px;
  &:focus-within { background: color-mix(in oklch, var(--ant-outline-ink) 3.5%, transparent); }
}
.ant-outline .ant-outline-tree .tog {
  display: grid; place-items: center; width: 20px; height: 30px; color: var(--ant-outline-faint); opacity: 0; transition: opacity .2s, color .2s;
  & svg { width: 13px; height: 13px; stroke-width: 2.2; transition: rotate .35s var(--ant-outline-spring); }
  &[aria-expanded="false"] { opacity: 1; }
  &[aria-expanded="false"] svg { rotate: -90deg; }
  &:hover { color: var(--ant-outline-ink); }
}
.ant-outline .ant-outline-tree .row:hover .tog, .ant-outline .ant-outline-tree .row:focus-within .tog { opacity: 1; }
.ant-outline .ant-outline-tree .sp { width: 20px; }
.ant-outline .ant-outline-tree .bul {
  position: relative; display: grid; place-items: center; width: 22px; height: 30px; border-radius: 50%;
  & i { width: 7px; height: 7px; border-radius: 50%; background: var(--ant-outline-mute); transition: scale .35s var(--ant-outline-spring), background .2s, box-shadow .2s; }
  &.has-kids.closed i { box-shadow: 0 0 0 5px var(--ant-outline-line2); }
  .row:focus-within > & i { background: var(--ant-outline-accent); box-shadow: 0 0 0 4px var(--ant-outline-tint); }
  &:hover i { scale: 1.45; background: var(--ant-outline-accent); }
}
.ant-outline .ant-outline-tree .txt {
  min-height: 30px; padding: 4px 6px 4px 4px; outline: none; border-radius: 5px; white-space: pre-wrap; overflow-wrap: anywhere; cursor: text; caret-color: var(--ant-outline-accent);
  font-size: 14.5px; line-height: 22px; text-wrap: pretty;
  &:empty::before { content: "Empty bullet"; color: var(--ant-outline-faint); }
  &[contenteditable="false"] { cursor: default; }
}
.ant-outline .ant-outline-tree .lvl1 > .row > .txt { font-weight: 640; }
.ant-outline .ant-outline-tree .cnt { position: absolute; right: 6px; top: 6px; font: 600 10.5px/18px ui-monospace, Menlo, monospace; padding: 0 6px; border-radius: 9px; color: var(--ant-outline-faint); background: var(--ant-outline-hover); pointer-events: none; }
.ant-outline .ant-outline-tree li.done > .row > .txt { color: var(--ant-outline-faint); text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--ant-outline-ink) 30%, transparent); }
.ant-outline .ant-outline-tree li.done > .row > .bul i { background: var(--ant-outline-faint); }
.ant-outline[data-hide="true"] .ant-outline-tree li.done { display: none; }
.ant-outline .ant-outline-tree li.hit > .row { background: color-mix(in oklch, var(--ant-outline-accent) 7%, transparent); }
.ant-outline .ant-outline-tree li.flash > .row { animation: ant-outline-flash 1.1s var(--ant-outline-ease); }
@keyframes ant-outline-flash { 0%, 30% { background: color-mix(in oklch, var(--ant-outline-accent) 22%, transparent); } }
.ant-outline .ant-outline-addroot {
  display: inline-flex; align-items: center; gap: 8px; margin: 8px 0 0 8px; height: 30px; padding: 0 10px; border-radius: 8px; font-size: 13px; color: var(--ant-outline-faint);
  &:hover { background: var(--ant-outline-hover); color: var(--ant-outline-ink); }
}
.ant-outline .ant-outline-empty { padding: 30px 30px; color: var(--ant-outline-mute); text-wrap: pretty; }
.ant-outline .ant-outline-foot {
  display: flex; align-items: center; gap: 16px; height: 34px; padding: 0 22px; flex: none; border-top: 1px solid var(--ant-outline-line); font: 11px ui-monospace, Menlo, monospace; color: var(--ant-outline-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden;
  & b { color: var(--ant-outline-mute); font-weight: 600; }
  & .msg { margin-left: auto; color: var(--ant-outline-accent); opacity: 0; transition: opacity .3s; }
  & .msg.on { opacity: 1; }
}
.ant-outline .ant-outline-scrim { position: absolute; inset: 0; z-index: 30; display: none; background: oklch(0 0 0 / .45); cursor: default; }

@container (width < 960px) {
  .ant-outline .ant-outline-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .ant-outline .ant-outline-side { position: absolute; inset: 0 auto 0 0; z-index: 40; width: 250px; translate: -104% 0; visibility: hidden; box-shadow: 20px 0 50px -20px #000; transition: translate .45s var(--ant-outline-spring), visibility 0s .45s; }
  .ant-outline[data-drawer="open"] .ant-outline-side { translate: 0 0; visibility: visible; transition-delay: 0s; }
  .ant-outline[data-drawer="open"] .ant-outline-scrim { display: block; }
  .ant-outline .ant-outline-top .ant-outline-drawerbtn { display: grid; margin-left: -10px; }
  .ant-outline .ant-outline-top { padding-left: 16px; }
}
@container (width < 640px) {
  .ant-outline .ant-outline-tools button span { display: none; }
  .ant-outline .ant-outline-tools button { padding: 0 8px; }
  .ant-outline .ant-outline-find { width: 120px; }
  .ant-outline .ant-outline-tree ul { margin-left: 20px; }
  .ant-outline .ant-outline-tree ul::before { left: -10px; }
  .ant-outline .ant-outline-title { margin-left: 22px; }
}
@container (width < 420px) {
  .ant-outline .ant-outline-top { flex-wrap: wrap; }
  .ant-outline .ant-outline-find { order: 3; width: 100%; }
  .ant-outline .ant-outline-doc { padding-inline: 12px 14px; }
  .ant-outline .ant-outline-tree ul { margin-left: 16px; }
  .ant-outline .ant-outline-tree ul::before { left: -8px; }
  .ant-outline .ant-outline-foot .dp { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .ant-outline *, .ant-outline *::before, .ant-outline *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; }
  .ant-outline .ant-outline-tree .tog { opacity: 1; }
}

