/* ── Branch · keyboard outliner ───────────────────────────────────────
   Bullets are plaintext contenteditable rows over one nested tree. Typing
   only updates the model; structural edits (split, indent, outdent, move,
   merge, complete, collapse) snapshot for undo, re-render, then FLIP every
   row from where it was. Zooming into a bullet flies its text up into the
   page title with a Web Animations transform. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const doc = root.ownerDocument;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const CE = (() => { const d = doc.createElement('div'); try { d.contentEditable = 'plaintext-only'; } catch (e) {} return d.contentEditable === 'plaintext-only' ? 'plaintext-only' : 'true'; })();
const CHEV = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg>';
const SEP = '<span class="sep" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m10 6 6 6-6 6"/></svg></span>';
let uid = 0;
const N = (text, kids, o) => Object.assign({ id: 'b' + (++uid), text, done: false, open: true, kids: kids || [] }, o || {});
const X = (text, kids) => N(text, kids, { done: true });
const DOCS = [
  { id: 'roadmap', name: 'Roadmap 2027', root: N('Roadmap 2027', [
    N('Q1 · Foundations', [
      N('Rebuild the rate engine', [N('Split pricing rules from carrier contracts'), N('Cache quotes for fifteen minutes'), X('Benchmark the old engine: 2.4 s at p95')]),
      N('Driver app offline mode', [N('Queue scans while there is no signal'), N('Rules for parcels scanned twice')]),
      X('Hire two backend engineers'),
    ]),
    N('Q2 · Customers', [
      N('Self-serve returns', [N('Print labels at drop-off points'), N('Refund status by email and SMS')]),
      N('Live arrival times on the tracking page'),
      N('Business accounts with monthly invoicing'),
    ]),
    N('Q3 · Scale', [
      N('Second depot in Rotterdam', [N('Lease signed by the end of Q1'), N('Night shift from day one')], { open: false }),
      N('Route planning for 400 vans'),
    ]),
    N('Open questions', [N('Fuel surcharge weekly or daily?'), N('Who owns carrier relationships after the merger?')]),
  ]) },
  { id: 'thesis', name: 'Thesis chapter plan', root: N('Thesis chapter plan', [
    N('1 Introduction', [N('Why city trees die young'), N('Research questions', [N('Does soil volume predict canopy at year ten?'), N('Do mixed-species streets outlive single-species ones?')])]),
    N('2 Literature', [X('Street tree survival studies'), N('Soil cells and structural soils')]),
