  --ant-meeting-line2: color-mix(in oklch, var(--ant-meeting-ink) 16%, transparent);
  --ant-meeting-hover: color-mix(in oklch, var(--ant-meeting-ink) 4.5%, transparent);
  --ant-meeting-mute: color-mix(in oklch, var(--ant-meeting-ink) 62%, var(--ant-meeting-bg));
  --ant-meeting-faint: color-mix(in oklch, var(--ant-meeting-ink) 42%, var(--ant-meeting-bg));
  --ant-meeting-tint: color-mix(in oklch, var(--ant-meeting-accent) 9%, var(--ant-meeting-bg));
  --ant-meeting-ease: cubic-bezier(.2, .8, .2, 1);
  --ant-meeting-spring: linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);
  --ant-meeting-mono: ui-monospace, Menlo, monospace;
  --ant-meeting-outw: 318px;

  position: relative; width: 100%; height: var(--ant-meeting-h, 680px); box-sizing: border-box; container-type: inline-size; overflow: clip; isolation: isolate;
  border-radius: 14px; background: var(--ant-meeting-bg); color: var(--ant-meeting-ink); color-scheme: light; accent-color: var(--ant-meeting-accent);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--ant-meeting-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
