  & kbd { display: inline-block; min-width: 16px; padding: 2px 4px; border-radius: 4px; text-align: center; font: 600 10px/1.2 var(--ant-meeting-mono); color: var(--ant-meeting-faint); box-shadow: inset 0 0 0 1px var(--ant-meeting-line2); }
  & h3 { font-size: 10.5px; font-weight: 720; letter-spacing: .1em; text-transform: uppercase; color: var(--ant-meeting-faint); }
  & .av { display: inline-grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; font-size: 9.5px; font-weight: 750; letter-spacing: .02em; color: oklch(0.25 0.04 var(--h)); background: oklch(0.88 0.07 var(--h)); flex: none; }
}
.ant-meeting .ant-meeting-app { height: 100%; display: grid; grid-template-columns: 244px minmax(0, 1fr) var(--ant-meeting-outw); grid-template-rows: minmax(0, 1fr); grid-template-areas: "list doc out"; }

/* list */
.ant-meeting .ant-meeting-list { grid-area: list; min-height: 0; display: flex; flex-direction: column; background: var(--ant-meeting-side); border-right: 1px solid var(--ant-meeting-line); }
.ant-meeting .ant-meeting-lhead { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 16px 12px 10px 16px; }
.ant-meeting .ant-meeting-brand { display: flex; align-items: center; gap: 9px; font-size: 15px; letter-spacing: -.02em;
  & svg { width: 24px; height: 24px; color: var(--ant-meeting-accent); stroke-width: 1.6; }
  & b { font-weight: 780; }
}
.ant-meeting .ant-meeting-new {
  display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 6px 0 7px; border-radius: 8px; font-size: 12px; font-weight: 680; background: var(--ant-meeting-ink); color: var(--ant-meeting-bg);
  & svg { width: 14px; height: 14px; }
  & kbd { color: color-mix(in oklch, var(--ant-meeting-bg) 70%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ant-meeting-bg) 30%, transparent); }
  &[aria-expanded="true"] { background: var(--ant-meeting-accent); }
}
.ant-meeting .ant-meeting-search {
  display: flex; align-items: center; gap: 7px; height: 32px; margin: 0 12px 8px; padding: 0 7px 0 9px; border-radius: 9px; background: var(--ant-meeting-bg); box-shadow: inset 0 0 0 1px var(--ant-meeting-line); cursor: text;
  & svg { color: var(--ant-meeting-faint); }
