  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--ant-meeting-accent); }
  &:focus-within kbd { opacity: 0; }
}
.ant-meeting .ant-meeting-mlist {
  flex: 1; min-height: 0; overflow-y: auto; padding: 0 8px 12px; scrollbar-width: thin; scrollbar-color: var(--ant-meeting-line2) transparent;
  & h4 { padding: 10px 8px 4px; font-size: 10.5px; font-weight: 720; letter-spacing: .1em; text-transform: uppercase; color: var(--ant-meeting-faint); }
  & .none { padding: 18px 10px; color: var(--ant-meeting-mute); font-size: 12.5px; }
}
.ant-meeting .ant-meeting-mi {
  display: grid; gap: 3px; width: 100%; padding: 9px 10px; border-radius: 10px; text-align: left; transition: background .2s;
  &:hover { background: var(--ant-meeting-hover); }
  &[aria-selected="true"] { background: var(--ant-meeting-bg); box-shadow: 0 0 0 1px var(--ant-meeting-line), 0 3px 10px -6px color-mix(in oklch, var(--ant-meeting-ink) 35%, transparent); }
  & .tt { font-size: 13px; font-weight: 640; letter-spacing: -.005em; line-height: 1.3; text-wrap: pretty; }
  & .mt { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; font-size: 11.5px; color: var(--ant-meeting-faint); font-variant-numeric: tabular-nums; }
  & .mt .tm, & .mt .open, & .mt .live { white-space: nowrap; }
  & .avs { display: flex; margin-left: auto; }
  & .avs .av { width: 18px; height: 18px; font-size: 8px; box-shadow: 0 0 0 2px var(--ant-meeting-side); }
  & .avs .av + .av { margin-left: -5px; }
  & .live { display: inline-flex; align-items: center; gap: 4px; color: var(--ant-meeting-accent); font-weight: 650; }
  & .live::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; animation: ant-meeting-pulse 1.6s ease-in-out infinite; }
  & .open { padding: 0 6px; border-radius: 9px; font-size: 10.5px; font-weight: 700; color: var(--ant-meeting-accent); background: var(--ant-meeting-tint); }
}
@keyframes ant-meeting-pulse { 50% { opacity: .35; } }

/* doc */
.ant-meeting .ant-meeting-doc { grid-area: doc; min-height: 0; min-width: 0; display: flex; flex-direction: column; }
.ant-meeting .ant-meeting-dbar { display: flex; align-items: center; gap: 8px; height: 50px; padding: 0 16px 0 22px; border-bottom: 1px solid var(--ant-meeting-line); flex: none; }
.ant-meeting .ant-meeting-dbar .ant-meeting-drawerbtn, .ant-meeting .ant-meeting-dbar .ant-meeting-seg { display: none; }
.ant-meeting .ant-meeting-ib { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; color: var(--ant-meeting-mute); flex: none; &:hover { background: var(--ant-meeting-hover); color: var(--ant-meeting-ink); } }
.ant-meeting .ant-meeting-tpl { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ant-meeting-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ant-meeting .ant-meeting-grow { flex: 1; }
.ant-meeting .ant-meeting-recapbtn {
  display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px 0 10px; border-radius: 9px; font-size: 12.5px; font-weight: 680; white-space: nowrap;
  color: var(--ant-meeting-bg); background: var(--ant-meeting-accent); box-shadow: 0 6px 16px -8px var(--ant-meeting-accent); transition: scale .3s var(--ant-meeting-spring), filter .2s;
  &:hover { filter: brightness(1.06); }
  &:active { scale: .95; }
  &[aria-expanded="true"] { background: var(--ant-meeting-ink); box-shadow: none; }
}
.ant-meeting .ant-meeting-scroll { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--ant-meeting-line2) transparent; }
.ant-meeting .ant-meeting-sheet { max-width: 720px; margin: 0 auto; padding: 22px clamp(18px, 3.4cqi, 40px) 50px; }
.ant-meeting .ant-meeting-title {
  width: 100%; padding: 0; border: 0; outline: none; background: none; font-size: clamp(21px, 2.4cqi, 28px); font-weight: 760; letter-spacing: -.03em; line-height: 1.2;
  &:focus-visible { box-shadow: 0 2px 0 var(--ant-meeting-accent); }
}
.ant-meeting .ant-meeting-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; margin: 8px 0 18px; font-size: 12.5px; color: var(--ant-meeting-mute); font-variant-numeric: tabular-nums;
  & .when { display: inline-flex; align-items: center; gap: 6px; }
}
.ant-meeting .ant-meeting-people {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px;
  & .chip { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 3px 0 3px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--ant-meeting-ink); background: var(--ant-meeting-hover); }
  & .chip > span:not(.av) { padding-right: 2px; }
  & .chip button { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; color: var(--ant-meeting-faint); }
  & .chip button:hover { background: var(--ant-meeting-line2); color: var(--ant-meeting-ink); }
  & .chip button svg { width: 11px; height: 11px; stroke-width: 2.2; }
  & .chip.me { padding-right: 10px; }
  & .add { display: inline-flex; align-items: center; gap: 4px; height: 28px; padding: 0 10px 0 8px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--ant-meeting-mute); box-shadow: inset 0 0 0 1px var(--ant-meeting-line2); }
  & .add:hover { color: var(--ant-meeting-ink); background: var(--ant-meeting-hover); }
  & .add svg { width: 13px; height: 13px; }
}
.ant-meeting .ant-meeting-agenda {
  display: grid; gap: 2px; margin: 8px 0 22px; padding: 6px; border-radius: 12px; background: var(--ant-meeting-side); counter-reset: ant-meeting-ag;
  & li { display: flex; align-items: center; gap: 10px; padding: 5px 6px; border-radius: 8px; counter-increment: ant-meeting-ag; }
  & li::after { content: counter(ant-meeting-ag, decimal-leading-zero); margin-left: auto; font: 600 10.5px var(--ant-meeting-mono); color: var(--ant-meeting-faint); }
  & button[role="checkbox"] { display: grid; place-items: center; width: 18px; height: 18px; border-radius: 5px; flex: none; background: var(--ant-meeting-bg); box-shadow: inset 0 0 0 1.5px var(--ant-meeting-line2); transition: background .25s, box-shadow .25s, scale .3s var(--ant-meeting-spring); }
  & button[role="checkbox"] svg { width: 12px; height: 12px; stroke-width: 2.6; color: var(--ant-meeting-bg); stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .3s var(--ant-meeting-ease); }
  & button[role="checkbox"]:active { scale: .85; }
  & button[aria-checked="true"] { background: var(--ant-meeting-ink); box-shadow: none; }
  & button[aria-checked="true"] svg { stroke-dashoffset: 0; }
  & li:has([aria-checked="true"]) span { color: var(--ant-meeting-faint); text-decoration: line-through; }
}
.ant-meeting .ant-meeting-nhead { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 6px; }
.ant-meeting .ant-meeting-nhead p { font-size: 11.5px; color: var(--ant-meeting-faint); text-align: right; text-wrap: pretty;
  & code { font: 11px var(--ant-meeting-mono); padding: 0 4px; border-radius: 4px; background: var(--ant-meeting-hover); color: var(--ant-meeting-mute); }
}
/* notes: transparent textarea over a line-by-line mirror */
.ant-meeting .ant-meeting-notes { position: relative; border-radius: 12px; box-shadow: inset 0 0 0 1px var(--ant-meeting-line); background: var(--ant-meeting-bg); transition: box-shadow .2s; }
.ant-meeting .ant-meeting-notes:focus-within { box-shadow: inset 0 0 0 1.5px var(--ant-meeting-ink); }
.ant-meeting .ant-meeting-notes textarea, .ant-meeting .ant-meeting-mirror {
  display: block; width: 100%; margin: 0; padding: 12px 14px 14px 40px; border: 0; font: 14px/1.75 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; letter-spacing: 0;
  white-space: pre-wrap; overflow-wrap: break-word; word-break: normal; tab-size: 4;
}
.ant-meeting .ant-meeting-notes textarea { position: relative; z-index: 1; min-height: 240px; resize: none; overflow: hidden; outline: none; background: transparent; caret-color: var(--ant-meeting-accent); }
.ant-meeting .ant-meeting-notes textarea::placeholder { color: var(--ant-meeting-faint); }
.ant-meeting .ant-meeting-mirror {
  position: absolute; inset: 0; color: transparent; pointer-events: none; overflow: hidden;
  & .ln { position: relative; border-radius: 5px; margin: 0 -6px; padding: 0 6px; transition: background .3s, box-shadow .3s; }
  & .ln > i { position: absolute; left: -26px; top: 0; height: 1.75em; display: grid; place-items: center; width: 18px; }
  & .ln > i svg { width: 14px; height: 14px; stroke-width: 2; }
  & .k-act { background: color-mix(in oklch, var(--ant-meeting-act) 8%, transparent); }
  & .k-act > i { color: var(--ant-meeting-act); }
  & .k-done { background: color-mix(in oklch, var(--ant-meeting-ink) 4%, transparent); }
  & .k-done > i { color: var(--ant-meeting-faint); }
  & .k-dec { background: color-mix(in oklch, var(--ant-meeting-dec) 10%, transparent); }
  & .k-dec > i { color: var(--ant-meeting-dec); }
  & .k-q { background: color-mix(in oklch, var(--ant-meeting-q) 12%, transparent); }
  & .k-q > i { color: var(--ant-meeting-q); }
  & .hot { box-shadow: inset 3px 0 0 currentColor, 0 0 0 2px color-mix(in oklch, var(--ant-meeting-accent) 30%, transparent); color: transparent; }
  & .k-act.hot { box-shadow: inset 0 0 0 1.5px var(--ant-meeting-act); background: color-mix(in oklch, var(--ant-meeting-act) 16%, transparent); }
  & .k-dec.hot { box-shadow: inset 0 0 0 1.5px var(--ant-meeting-dec); }
  & .k-q.hot { box-shadow: inset 0 0 0 1.5px var(--ant-meeting-q); }
  & .new > i { animation: ant-meeting-pop .5s var(--ant-meeting-spring); }
}
@keyframes ant-meeting-pop { from { scale: 0; } }

/* extracted panel */
.ant-meeting .ant-meeting-out { grid-area: out; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 16px; padding: 16px 14px 18px; background: var(--ant-meeting-side); border-left: 1px solid var(--ant-meeting-line); }
.ant-meeting .ant-meeting-sum { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;
  & div { padding: 9px 10px; border-radius: 10px; background: var(--ant-meeting-bg); box-shadow: inset 0 0 0 1px var(--ant-meeting-line); }
  & b { display: block; font-size: 20px; font-weight: 700; letter-spacing: -.03em; line-height: 1.1; font-variant-numeric: tabular-nums; }
  & span { font-size: 10.5px; color: var(--ant-meeting-faint); }
  & .a b { color: var(--ant-meeting-act); } & .d b { color: var(--ant-meeting-dec); } & .q b { color: var(--ant-meeting-q); }
}
.ant-meeting .ant-meeting-grp > h3 { display: flex; align-items: center; gap: 6px; margin-bottom: 6px; padding: 0 2px; }
.ant-meeting .ant-meeting-grp > h3 i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
.ant-meeting .ant-meeting-grp > h3 output { margin-left: auto; letter-spacing: 0; font-variant-numeric: tabular-nums; }
.ant-meeting .ant-meeting-grp .empty { padding: 8px 10px; border-radius: 10px; font-size: 12px; color: var(--ant-meeting-faint); box-shadow: inset 0 0 0 1px var(--ant-meeting-line2); text-wrap: pretty; }
.ant-meeting .ant-meeting-ai {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 4px 9px; align-items: start; padding: 9px 8px 9px 10px; border-radius: 11px; background: var(--ant-meeting-bg);
  box-shadow: 0 0 0 1px var(--ant-meeting-line); transition: box-shadow .2s, translate .3s var(--ant-meeting-spring);
  & + .ant-meeting-ai { margin-top: 5px; }
  &:hover, &:focus-within { box-shadow: 0 0 0 1px var(--ant-meeting-line2), 0 6px 16px -10px color-mix(in oklch, var(--ant-meeting-ink) 40%, transparent); }
  &.is-new { animation: ant-meeting-in .5s var(--ant-meeting-spring); }
  & .ck { display: grid; place-items: center; width: 18px; height: 18px; margin-top: 1px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--ant-meeting-act); transition: background .25s, scale .3s var(--ant-meeting-spring); }
  & .ck svg { width: 11px; height: 11px; stroke-width: 2.8; color: var(--ant-meeting-bg); opacity: 0; transition: opacity .2s; }
  & .ck:active { scale: .85; }
  & .ck[aria-checked="true"] { background: var(--ant-meeting-act); }
  & .ck[aria-checked="true"] svg { opacity: 1; }
  & .tx { font-size: 12.5px; font-weight: 560; line-height: 1.4; text-wrap: pretty; }
  &:has(.ck[aria-checked="true"]) .tx { color: var(--ant-meeting-faint); text-decoration: line-through; }
  & .jump { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 6px; color: var(--ant-meeting-faint); }
  & .jump:hover { background: var(--ant-meeting-hover); color: var(--ant-meeting-ink); }
  & .jump svg { width: 13px; height: 13px; }
  & .who { grid-column: 2 / -1; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
  & .who button { display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px 0 2px; border-radius: 99px; font-size: 11.5px; font-weight: 600; color: var(--ant-meeting-mute); box-shadow: inset 0 0 0 1px var(--ant-meeting-line2); }
  & .who button:hover { color: var(--ant-meeting-ink); background: var(--ant-meeting-hover); }
  & .who button .av { width: 20px; height: 20px; font-size: 8px; }
  & .who button.un { padding-left: 8px; color: var(--ant-meeting-act); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ant-meeting-act) 40%, transparent); }
  & .due { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; color: var(--ant-meeting-mute); font-variant-numeric: tabular-nums; }
  & .due svg { width: 12px; height: 12px; }
}
@keyframes ant-meeting-in { from { opacity: 0; translate: 0 6px; } }
.ant-meeting .ant-meeting-di {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px; align-items: start; padding: 8px 8px 8px 12px; border-radius: 10px; background: var(--ant-meeting-bg); box-shadow: inset 3px 0 0 var(--c), 0 0 0 1px var(--ant-meeting-line);
  & + .ant-meeting-di { margin-top: 5px; }
  & p { font-size: 12.5px; line-height: 1.45; text-wrap: pretty; }
  & .acts { display: flex; gap: 2px; }
  & .acts button { height: 24px; padding: 0 7px; border-radius: 6px; font-size: 11px; font-weight: 650; color: var(--ant-meeting-mute); white-space: nowrap; }
  & .acts button:hover { background: var(--ant-meeting-hover); color: var(--ant-meeting-ink); }
  & .acts .jump { display: grid; place-items: center; width: 24px; padding: 0; }
  & .acts svg { width: 13px; height: 13px; }
}

/* overlays */
.ant-meeting .ant-meeting-menu {
  position: absolute; z-index: 70; min-width: 200px; padding: 5px; border-radius: 12px; background: var(--ant-meeting-bg); display: grid;
  box-shadow: 0 0 0 1px var(--ant-meeting-line2), 0 20px 44px -16px color-mix(in oklch, var(--ant-meeting-ink) 45%, transparent);
  transition: opacity .18s, scale .3s var(--ant-meeting-spring); transform-origin: top left;
  @starting-style { opacity: 0; scale: .94; }
  & .h { padding: 6px 9px 4px; font-size: 10.5px; font-weight: 720; letter-spacing: .1em; text-transform: uppercase; color: var(--ant-meeting-faint); }
  & button { display: flex; align-items: center; gap: 9px; min-height: 32px; padding: 4px 9px; border-radius: 8px; text-align: left; font-size: 12.5px; font-weight: 540; }
  & button small { display: block; font-size: 11px; color: var(--ant-meeting-faint); }
  & button:hover, & button:focus-visible { background: var(--ant-meeting-hover); outline: none; }
  & button:focus-visible { box-shadow: inset 0 0 0 1.5px var(--ant-meeting-accent); }
  & button[aria-checked="true"] { font-weight: 680; }
  & button[aria-checked="true"]::after { content: ""; width: 9px; height: 5px; margin: -3px 2px 0 auto; border: solid var(--ant-meeting-accent); border-width: 0 0 2px 2px; rotate: -45deg; }
}
.ant-meeting .ant-meeting-modal { position: absolute; z-index: 65; top: 0; right: 0; bottom: 0; width: var(--ant-meeting-outw); padding: 10px; display: grid; transition: opacity .2s; @starting-style { opacity: 0; } }
.ant-meeting .ant-meeting-dialog {
  min-height: 0; display: flex; flex-direction: column; border-radius: 16px; background: var(--ant-meeting-bg); box-shadow: 0 0 0 1px var(--ant-meeting-line2), 0 30px 60px -20px color-mix(in oklch, var(--ant-meeting-ink) 55%, transparent);
  transition: translate .5s var(--ant-meeting-spring); @starting-style { translate: 24px 0; }
  & header { display: flex; align-items: center; gap: 8px; padding: 14px 10px 10px 16px; border-bottom: 1px solid var(--ant-meeting-line); }
  & h2 { flex: 1; font-size: 15px; font-weight: 750; letter-spacing: -.01em; }
  & .to { padding: 10px 16px 0; font-size: 12px; color: var(--ant-meeting-mute); }
  & .to b { color: var(--ant-meeting-ink); }
  & pre { flex: 1; min-height: 0; overflow: auto; margin: 10px 12px; padding: 12px 14px; border-radius: 12px; background: var(--ant-meeting-side); font: 12px/1.6 var(--ant-meeting-mono); white-space: pre-wrap; color: var(--ant-meeting-ink); }
  & footer { display: flex; gap: 6px; padding: 0 12px 12px; }
  & footer button { flex: 1; height: 34px; border-radius: 9px; font-weight: 680; font-size: 12.5px; box-shadow: inset 0 0 0 1px var(--ant-meeting-line2); }
  & footer .pri { background: var(--ant-meeting-ink); color: var(--ant-meeting-bg); box-shadow: none; }
  & footer button:hover { filter: brightness(1.06); background-color: var(--ant-meeting-hover); }
  & footer .pri:hover { background: color-mix(in oklch, var(--ant-meeting-ink) 88%, var(--ant-meeting-accent)); }
}
.ant-meeting .ant-meeting-scrim { position: absolute; inset: 0; z-index: 30; display: none; background: color-mix(in oklch, var(--ant-meeting-ink) 25%, transparent); cursor: default; }
.ant-meeting .ant-meeting-toast {
  position: absolute; z-index: 80; left: 50%; bottom: 18px; translate: -50% 0; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
  padding: 7px 7px 7px 14px; border-radius: 12px; background: var(--ant-meeting-ink); color: var(--ant-meeting-bg); font-size: 12.5px; font-weight: 600;
  box-shadow: 0 16px 34px -14px var(--ant-meeting-ink); transition: translate .5s var(--ant-meeting-spring), opacity .2s;
  @starting-style { translate: -50% 16px; opacity: 0; }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { flex: none; height: 26px; padding: 0 10px; border-radius: 7px; font-weight: 750; background: var(--ant-meeting-bg); color: var(--ant-meeting-ink); }
  &.no-undo button { display: none; }
}

@container (width < 1080px) { .ant-meeting { --ant-meeting-outw: 290px; } .ant-meeting .ant-meeting-app { grid-template-columns: 220px minmax(0, 1fr) var(--ant-meeting-outw); } }
@container (width < 960px) {
  .ant-meeting .ant-meeting-app { grid-template-columns: minmax(0, 1fr) var(--ant-meeting-outw); grid-template-areas: "doc out"; }
