/* ── Minutes · meeting notes that extract their own action items ──────
   The notes text is the only source of truth. Every keystroke re-reads it
   line by line into actions (a [ ] box, TODO:, or "@Name to …"), decisions
   ("Decision:", "We agreed …") and open questions (a line ending in "?").
   A mirror layer behind the transparent textarea bands each line by kind
   with a gutter marker, and every change made from the side panel (tick,
   reassign, turn a question into an action) is written back into the text. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const doc = root.ownerDocument;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const fold = s => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const DAY = 864e5, TODAY = Math.round(Date.UTC(2026, 9, 2) / DAY);
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const dow = n => ((n + 4) % 7 + 7) % 7;
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const dlabel = n => WD[dow(n)] + ' ' + ymd(n)[2] + ' ' + MON[ymd(n)[1]];
const I = {
  act: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="m8.5 12.2 2.4 2.4 4.6-4.8"/></svg>',
  dec: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3v18M5 7h14l-2 4H7Z"/></svg>',
  q: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9.5 9a2.5 2.5 0 1 1 3.5 2.3c-.6.3-1 .9-1 1.6v.6M12 17h.01"/></svg>',
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5.5 12.5 4 4L18.5 8"/></svg>',
  jump: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7M9 7h8v8"/></svg>',
  cal: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="15" rx="2.5"/><path d="M4 9.5h16M8.5 3v4M15.5 3v4"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6v12M6 12h12"/></svg>',
  clock: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 8v4.5l3 1.8"/></svg>',
};
const PEOPLE = {
  sam: { name: 'Sam Okoro', ini: 'SO', h: 30 },
  priya: { name: 'Priya Raman', ini: 'PR', h: 350 },
  tomas: { name: 'Tomás Ferreira', ini: 'TF', h: 155 },
  hana: { name: 'Hana Kobayashi', ini: 'HK', h: 250 },
  dele: { name: 'Dele Adeyemi', ini: 'DA', h: 80 },
  ingrid: { name: 'Ingrid Halden', ini: 'IH', h: 200 },
};
const first = k => PEOPLE[k].name.split(' ')[0];
const av = k => '<span class="av" style="--h:' + PEOPLE[k].h + '" aria-hidden="true">' + PEOPLE[k].ini + '</span>';
const TPL = {
  client: { name: 'Client review', agenda: ['Progress since the last review', 'Decisions we need from you', 'Next milestones'] },
  one: { name: '1:1', agenda: ['How are you, really?', 'Wins since last time', 'Anything blocking you', 'Growth and feedback'] },
  weekly: { name: 'Weekly sync', agenda: ['Last week’s actions', 'Numbers', 'Priorities this week', 'Risks'] },
  retro: { name: 'Retro', agenda: ['What went well', 'What did not', 'What we will try next'] },
