const M = (id, title, day, time, tpl, people, agendaDone, notes, o) => Object.assign({ id, title, day, time, tpl, people, agenda: TPL[tpl].agenda.map((t, i) => ({ t, done: i < agendaDone })), notes: notes.trim(), sent: false }, o || {});
let meetings = [
  M('m1', 'Halden launch sync', TODAY, '10:00–10:45', 'client', ['sam', 'priya', 'tomas', 'ingrid'], 2, `
Launch moves to Tue 20 Oct. Ingrid wants a week of soft launch with the mailing list first.
Decision: code freeze on Wed 14 Oct, only copy changes after that.
@Priya to send the final shot list to Ingrid by Monday

Photography: 24 products, natural light, grey backdrop. Two studio days.
[ ] Tomás to set up the staging store with the 24 SKUs by Thu
The wholesale portal is bigger than we thought: logins, price tiers, invoices.
We agreed the wholesale portal ships in phase 2, not at launch.
Can we reuse the old tax rules or do we need a new provider?
@Sam will draft the soft-launch email by Fri 9 Oct
Ingrid asked about gift wrapping at checkout. Nice to have.
Who signs off the final copy on their side?
[x] Share moodboard v3 with the team`, { live: true }),
  M('m2', '1:1 with Priya', TODAY, '15:30–16:00', 'one', ['sam', 'priya'], 0, ''),
  M('m3', 'Design crit: onboarding v2', TODAY - 1, '14:00–15:00', 'weekly', ['sam', 'hana', 'priya'], 4, `
Hana walked through the new three-step onboarding.
Step two is too long on small phones. Cut the illustration.
Decision: drop the account-type question, infer it from the first project.
@Hana to update the prototype by Tuesday
Do we still need the welcome email if the checklist does the same job?
[x] Book a usability session with two new customers`),
  M('m4', 'Hiring panel debrief', TODAY - 1, '11:00–11:30', 'weekly', ['sam', 'dele', 'hana'], 4, `
Candidate: Laia, product designer.
Strong portfolio, best case study of the round. Whiteboard exercise was rushed.
Decided: move Laia to the final round.
[ ] Dele to book the final interview by Wed
[ ] Sam to send feedback to the agency`),
  M('m5', 'Weekly product sync', TODAY - 4, '09:30–10:00', 'weekly', ['sam', 'priya', 'tomas', 'hana', 'dele'], 4, `
Sign-ups up 9% week on week, mostly from the referral link.
Checkout errors down to 0.4% after Tomás’s fix.
[x] Tomás to ship the checkout retry fix
[x] Priya to share the referral numbers
Decision: pause paid social until the new landing page is live.`),
  M('m6', 'Retro: sprint 13', TODAY - 3, '16:00–16:45', 'retro', ['sam', 'tomas', 'hana', 'dele'], 3, `
Went well: releases every day, no rollbacks.
Didn’t: too many meetings on Wednesday.
We agreed to move standup to async on Wednesdays.
[ ] Dele to try a no-meeting Wednesday next sprint
Should we split the frontend board in two?`),
];
const S = { sel: 'm1', q: '', menu: null, lastKeys: new Set(), undo: null };
const cur = () => meetings.find(m => m.id === S.sel);

/* ── extraction ── */
const DUE = /\bby\s+((?:mon|tue|wed|thu|fri|sat|sun)[a-z]*\.?(?:\s+\d{1,2}\s+(?:sep|oct|nov|dec)[a-z]*)?|tomorrow|eod|end of (?:the )?week|next week|\d{1,2}\s+(?:sep|oct|nov|dec)[a-z]*|(?:sep|oct|nov|dec)[a-z]*\s+\d{1,2})\b/i;
const WDN = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 }, MN = { sep: 8, oct: 9, nov: 10, dec: 11 };
function dueFrom(s, base) {
  s = s.toLowerCase();
  if (s === 'tomorrow') return base + 1;
  if (s === 'eod') return base;
  if (/end of/.test(s)) { let n = base; while (dow(n) !== 5) n++; return n; }
  if (s === 'next week') { let n = base + 1; while (dow(n) !== 1) n++; return n; }
  let m = s.match(/(\d{1,2})\s+([a-z]{3})/) || s.match(/([a-z]{3})[a-z]*\s+(\d{1,2})/);
  if (m) { const day = +(isNaN(m[1]) ? m[2] : m[1]), mo = MN[(isNaN(m[1]) ? m[1] : m[2]).slice(0, 3)]; if (mo != null) return Math.round(Date.UTC(2026, mo, day) / DAY); }
  const k = WDN[s.slice(0, 3)]; if (k != null) { let n = base + 1; while (dow(n) !== k) n++; return n; }
  return null;
}
function who(line, m) {
  const at = line.match(/@([\p{L}]+)/u);
  const keys = m.people.concat(Object.keys(PEOPLE).filter(k => !m.people.includes(k)));
  if (at) { const k = keys.find(k => fold(first(k)) === fold(at[1])); return k ? { key: k, at: true } : { key: null, raw: at[1] }; }
  const lead = line.match(/^([\p{L}]+)\s+(?:to|will|should|needs to)\b/u);
  if (lead) { const k = keys.find(k => fold(first(k)) === fold(lead[1])); if (k) return { key: k, at: false }; }
  return null;
}
function extract(m) {
  const out = { acts: [], decs: [], qs: [], kinds: [] };
  m.notes.split('\n').forEach((raw, i) => {
    const line = raw.trim();
    if (!line) return out.kinds.push(null);
    const box = line.match(/^(?:[-*]\s*)?\[( |x|X)\]\s*/), todo = line.match(/^(?:todo|action|ai)\s*[:\-]\s*/i);
    let body = line.slice(box ? box[0].length : todo ? todo[0].length : 0);
    const w = who(body, m);
    const mentionAct = /@[\p{L}]+\s+(?:to|will|should|needs to|must)\b/u.test(body) || /^@[\p{L}]+/u.test(body);
    if (box || todo || mentionAct) {
      const done = !!box && box[1] !== ' ';
      const dm = body.match(DUE), due = dm ? dueFrom(dm[1], m.day) : null;
      let txt = body.replace(DUE, '').replace(/@[\p{L}]+\s*/u, '').replace(/^(?:to|will|should|needs to|must)\s+/i, '');
      if (w && !w.at) txt = txt.replace(new RegExp('^' + first(w.key).normalize('NFC') + '\\s+(?:to|will|should|needs to)\\s+', 'iu'), '').replace(/^[\p{L}]+\s+(?:to|will|should|needs to)\s+/u, '');
      txt = txt.replace(/\s+/g, ' ').trim(); txt = txt.charAt(0).toUpperCase() + txt.slice(1);
      out.acts.push({ i, done, who: w && w.key, unknown: w && !w.key ? w.raw : null, due, text: txt || 'Untitled action' });
      return out.kinds.push(done ? 'done' : 'act');
    }
    if (/^(?:decision|decided|agreed)\b\s*[:\-]?\s*/i.test(line) || /^we (?:agreed|decided)\b/i.test(line)) {
      let t = line.replace(/^(?:decision|decided|agreed)\b\s*[:\-]?\s*/i, '').replace(/^we (?:agreed|decided)\s+(?:to\s+|that\s+)?/i, '');
      out.decs.push({ i, text: t.charAt(0).toUpperCase() + t.slice(1) }); return out.kinds.push('dec');
    }
    if (/\?\s*$/.test(line)) { out.qs.push({ i, text: line }); return out.kinds.push('q'); }
    out.kinds.push(null);
