}

/* ── render ── */
function keep(box, fn) { const a = doc.activeElement, k = a && box.contains(a) ? a.dataset.k : null; fn(); if (k) { const el = box.querySelector('[data-k="' + k + '"]'); if (el) el.focus({ preventScroll: true }); } }
function renderList() {
