  const grp = m => m.day === TODAY ? 'Today' : m.day === TODAY - 1 ? 'Yesterday' : 'Earlier this week';
  let h = '', last = '';
  L.forEach(m => {
    const g = grp(m); if (g !== last) { h += '<h4>' + g + '</h4>'; last = g; }
