    h += '<button type="button" class="ant-meeting-mi" role="option" data-k="m' + m.id + '" data-meet="' + m.id + '" aria-selected="' + (m.id === S.sel) + '" tabindex="' + (m.id === S.sel ? 0 : -1) + '">' +
      '<span class="tt">' + esc(m.title) + '</span><span class="mt">' + (m.live ? '<span class="live">Now</span>' : '') + '<span class="tm">' + m.time + '</span>' + (open ? '<span class="open">' + open + ' open</span>' : m.sent ? '<span>· recap sent</span>' : '') +
      '<span class="avs">' + m.people.slice(0, 4).map(av).join('') + '</span></span></button>';
