      '<section class="ant-meeting-grp"><h3><i style="--c:var(--ant-meeting-dec)"></i>Decisions</h3>' + (x.decs.map(d => di(d, 'var(--ant-meeting-dec)')).join('') || '<p class="empty">Start a line with “Decision:” to record one.</p>') + '</section>' +
