function renderAll() { renderList(); renderDoc(); }

/* ── text rewrites from the panel ── */
function rewrite(i, fn, msg) {
  const m = cur(), lines = m.notes.split('\n'), before = m.notes;
  lines[i] = fn(lines[i]); m.notes = lines.join('\n');
  const ta = $('[data-notes]'); if (ta) ta.value = m.notes;
