    if (/@[\p{L}]+/u.test(l)) return l.replace(/@[\p{L}]+/u, '@' + name);
    const pre = l.match(/^(\s*(?:[-*]\s*)?(?:\[( |x|X)\]\s*)?(?:(?:todo|action|ai)\s*[:\-]\s*)?)/i)[1], rest = l.slice(pre.length);
    const lead = rest.match(/^([\p{L}]+)(\s+(?:to|will|should|needs to)\b)/u);
    if (lead && Object.keys(PEOPLE).some(k => fold(first(k)) === fold(lead[1]))) return pre + name + rest.slice(lead[1].length);
