css:
@property --ant-review-p { syntax: "<number>"; inherits: true; initial-value: 0; }
.ant-review {
  /* re-theme with these four */
  --ant-review-bg: oklch(0.19 0.02 55);
  --ant-review-ink: oklch(0.95 0.02 82);
  --ant-review-accent: oklch(0.8 0.15 76);
  --ant-review-panel: oklch(0.225 0.022 55);
  /* derived */
  --ant-review-good: oklch(0.76 0.09 150);
  --ant-review-bad: oklch(0.7 0.16 30);
  --ant-review-line: color-mix(in oklch, var(--ant-review-ink) 9%, transparent);
  --ant-review-line2: color-mix(in oklch, var(--ant-review-ink) 16%, transparent);
  --ant-review-hover: color-mix(in oklch, var(--ant-review-ink) 6%, transparent);
  --ant-review-mute: color-mix(in oklch, var(--ant-review-ink) 64%, var(--ant-review-bg));
  --ant-review-faint: color-mix(in oklch, var(--ant-review-ink) 40%, var(--ant-review-bg));
  --ant-review-tint: color-mix(in oklch, var(--ant-review-accent) 14%, transparent);
  --ant-review-on: oklch(0.22 0.04 60);
  --ant-review-ease: cubic-bezier(.2, .8, .2, 1);
  --ant-review-spring: linear(0, 0.1 5%, 0.38 11%, 0.72 18%, 0.94 25%, 1.04 31%, 1.06 37%, 1.03 45%, 1.005 56%, 0.998 70%, 1);

  position: relative; width: 100%; height: var(--ant-review-h, 680px); box-sizing: border-box; container-type: inline-size; overflow: clip; isolation: isolate;
  border-radius: 18px; background: var(--ant-review-bg); color: var(--ant-review-ink); color-scheme: dark; accent-color: var(--ant-review-accent);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--ant-review-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .38; }
  & h2, & h3, & h4, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-block; min-width: 16px; padding: 2px 4px; border-radius: 4px; text-align: center; font: 600 10px/1.2 ui-monospace, Menlo, monospace; color: var(--ant-review-mute); box-shadow: inset 0 0 0 1px var(--ant-review-line2); }
  & h3 { font-size: 10.5px; font-weight: 720; letter-spacing: .1em; text-transform: uppercase; color: var(--ant-review-faint); }
}
.ant-review .ant-review-app { height: 100%; display: grid; grid-template-columns: 252px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "rail main"; }

/* rail */
.ant-review .ant-review-rail { grid-area: rail; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 18px; padding: 20px 14px 16px; background: var(--ant-review-panel); border-right: 1px solid var(--ant-review-line); }
.ant-review .ant-review-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px;
  & svg { width: 28px; height: 28px; color: var(--ant-review-accent); stroke-width: 1.5; }
  & span { display: grid; line-height: 1.2; }
  & b { font-size: 16px; font-weight: 780; letter-spacing: -.02em; }
  & small { font-size: 11px; color: var(--ant-review-faint); }
}
.ant-review .ant-review-prog {
  display: flex; align-items: center; gap: 12px; padding: 12px; border-radius: 14px; background: var(--ant-review-hover);
  & .ring { --ant-review-p: var(--p, 0); position: relative; width: 46px; height: 46px; flex: none; border-radius: 50%;
    background: conic-gradient(var(--ant-review-accent) calc(var(--ant-review-p) * 1turn), var(--ant-review-line2) 0);
    mask: radial-gradient(farthest-side, transparent calc(100% - 6px), #000 calc(100% - 5.5px)); transition: --ant-review-p .9s var(--ant-review-spring); }
  & .n { position: absolute; width: 46px; text-align: center; font: 750 13px/46px system-ui, sans-serif; font-variant-numeric: tabular-nums; }
  & .rw { position: relative; }
  & b { display: block; font-size: 13px; font-weight: 680; }
  & small { font-size: 11.5px; color: var(--ant-review-faint); }
}
.ant-review .ant-review-steps {
  display: grid; gap: 2px; counter-reset: ant-review-s;
  & button { position: relative; display: grid; grid-template-columns: 28px minmax(0, 1fr); align-items: center; gap: 10px; width: 100%; padding: 8px 8px; border-radius: 11px; text-align: left; transition: background .2s; }
  & button:hover { background: var(--ant-review-hover); }
  & button[aria-current="step"] { background: var(--ant-review-tint); }
  & .dot { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; font: 700 12px/1 system-ui, sans-serif; color: var(--ant-review-mute); box-shadow: inset 0 0 0 1.5px var(--ant-review-line2); transition: background .3s, color .3s, box-shadow .3s; }
  & .dot svg { width: 14px; height: 14px; stroke-width: 2.6; }
  & [aria-current="step"] .dot { color: var(--ant-review-accent); box-shadow: inset 0 0 0 1.5px var(--ant-review-accent); }
  & .ok .dot { background: var(--ant-review-good); color: var(--ant-review-on); box-shadow: none; }
  & .t { display: grid; line-height: 1.25; min-width: 0; }
  & .t b { font-size: 13px; font-weight: 640; }
  & .t small { font-size: 11.5px; color: var(--ant-review-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & li + li button::before { content: ""; position: absolute; left: 21.5px; top: -9px; width: 1px; height: 12px; background: var(--ant-review-line2); }
}
.ant-review .ant-review-tip { margin-top: auto; padding: 0 6px; font-size: 11.5px; color: var(--ant-review-faint); text-wrap: pretty; & b { color: var(--ant-review-mute); font-weight: 600; } }

/* main */
.ant-review .ant-review-main { grid-area: main; min-height: 0; min-width: 0; display: flex; flex-direction: column; }
.ant-review .ant-review-head { padding: 22px 28px 12px; display: grid; gap: 4px;
  & .k { font-size: 11px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; color: var(--ant-review-accent); }
  & h2 { font-size: clamp(22px, 2.5cqi, 30px); font-weight: 760; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
  & p { max-width: 62ch; color: var(--ant-review-mute); text-wrap: pretty; }
}
.ant-review .ant-review-body { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 8px 28px 20px; scrollbar-width: thin; scrollbar-color: var(--ant-review-line2) transparent; }
.ant-review .ant-review-body > * { animation: ant-review-enter .5s var(--ant-review-ease) backwards; animation-delay: calc(var(--i, 0) * 50ms); }
@keyframes ant-review-enter { from { opacity: 0; translate: 0 8px; } }
.ant-review .ant-review-nav { display: flex; align-items: center; gap: 8px; padding: 12px 28px; border-top: 1px solid var(--ant-review-line);
  & .sp { flex: 1; font-size: 11.5px; color: var(--ant-review-faint); }
  & button { display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 14px; border-radius: 10px; font-weight: 680; font-size: 13px; box-shadow: inset 0 0 0 1px var(--ant-review-line2); transition: background .2s, scale .3s var(--ant-review-spring); }
  & button:hover:not(:disabled) { background: var(--ant-review-hover); }
  & button:active { scale: .96; }
  & .pri { background: var(--ant-review-accent); color: var(--ant-review-on); box-shadow: none; }
  & .pri:hover:not(:disabled) { background: color-mix(in oklch, var(--ant-review-accent) 88%, white); }
}

/* step 1: inbox */
.ant-review .ant-review-tally { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px;
  & span { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 99px; font-size: 12px; color: var(--ant-review-mute); background: var(--ant-review-hover); font-variant-numeric: tabular-nums; }
  & b { color: var(--ant-review-ink); }
  & .keys { background: none; margin-left: auto; gap: 4px; color: var(--ant-review-faint); }
}
.ant-review .ant-review-inbox { display: grid; gap: 6px; }
.ant-review .ant-review-in.is-out { pointer-events: none; }
.ant-review .ant-review-in {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 6px 12px; padding: 11px 12px 11px 14px; border-radius: 12px; background: var(--ant-review-panel); box-shadow: inset 0 0 0 1px var(--ant-review-line);
  & .tx b { display: block; font-size: 13.5px; font-weight: 600; text-wrap: pretty; }
  & .tx small { font-size: 11.5px; color: var(--ant-review-faint); }
  & .acts { display: flex; gap: 4px; flex-wrap: wrap; justify-content: flex-end; }
  & .acts button { display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 640; color: var(--ant-review-mute); box-shadow: inset 0 0 0 1px var(--ant-review-line2); transition: background .2s, color .2s; }
  & .acts button svg { width: 14px; height: 14px; }
  & .acts button:hover { color: var(--ant-review-ink); background: var(--ant-review-hover); }
  & .acts [data-do="done"]:hover { color: var(--ant-review-good); }
  & .acts [data-do="plan"]:hover { color: var(--ant-review-accent); }
  & .acts [data-do="drop"]:hover { color: var(--ant-review-bad); }
}
.ant-review .ant-review-clear { display: grid; justify-items: center; gap: 8px; padding: 36px 20px; border-radius: 16px; text-align: center; color: var(--ant-review-mute); background: var(--ant-review-hover);
  & svg { width: 36px; height: 36px; color: var(--ant-review-good); stroke-width: 1.4; }
  & b { font-size: 16px; color: var(--ant-review-ink); }
}

/* step 2: look back */
.ant-review .ant-review-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-bottom: 16px;
  & div { padding: 12px 14px; border-radius: 13px; background: var(--ant-review-panel); box-shadow: inset 0 0 0 1px var(--ant-review-line); }
  & b { display: block; font-size: 24px; font-weight: 680; letter-spacing: -.04em; line-height: 1.1; font-variant-numeric: tabular-nums; }
  & span { font-size: 11.5px; color: var(--ant-review-faint); }
