}
.ant-review .ant-review-cols { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 16px; }
.ant-review .ant-review-card { padding: 14px 16px; border-radius: 14px; background: var(--ant-review-panel); box-shadow: inset 0 0 0 1px var(--ant-review-line); }
.ant-review .ant-review-card > h3 { margin-bottom: 12px; display: flex; justify-content: space-between; }
.ant-review .ant-review-card > h3 output { letter-spacing: 0; text-transform: none; color: var(--ant-review-mute); font-variant-numeric: tabular-nums; }
.ant-review .ant-review-bars {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; height: 150px; align-items: end;
  & div { display: grid; grid-template-rows: auto 1fr auto; justify-items: center; gap: 5px; height: 100%; }
  & .stack { align-self: end; width: 100%; max-width: 40px; display: flex; flex-direction: column-reverse; gap: 2px; height: calc(var(--v) * 1%); }
  & .stack i { display: block; border-radius: 3px; }
  & .stack .d { flex: var(--d) 1 0; background: var(--ant-review-accent); }
  & .stack .m { flex: var(--m) 1 0; background: var(--ant-review-line2); }
  & small { font-size: 11px; font-weight: 650; font-variant-numeric: tabular-nums; }
  & em { font-style: normal; font-size: 11px; color: var(--ant-review-faint); }
  & .stack { transform-origin: bottom; animation: ant-review-grow .8s var(--ant-review-spring) backwards; animation-delay: calc(var(--i) * 60ms); }
}
@keyframes ant-review-grow { from { scale: 1 0; } }
.ant-review .ant-review-legend { display: flex; gap: 14px; margin-top: 10px; font-size: 11px; color: var(--ant-review-faint);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
}
.ant-review .ant-review-wins {
  display: grid; gap: 4px;
  & li { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; gap: 8px; align-items: start; padding: 6px 2px; font-size: 13px; border-bottom: 1px solid var(--ant-review-line); }
  & li svg { width: 16px; height: 16px; color: var(--ant-review-accent); margin-top: 1px; }
  & li button { width: 22px; height: 22px; display: grid; place-items: center; border-radius: 6px; color: var(--ant-review-faint); }
  & li button:hover { background: var(--ant-review-hover); color: var(--ant-review-ink); }
  & li button svg { width: 12px; height: 12px; color: currentColor; margin: 0; }
  & li.new { animation: ant-review-pop .5s var(--ant-review-spring); }
}
@keyframes ant-review-pop { from { opacity: 0; scale: .96; } }
.ant-review .ant-review-addwin { display: flex; gap: 6px; margin-top: 10px;
  & input { flex: 1; min-width: 0; height: 32px; padding: 0 10px; border: 0; border-radius: 8px; outline: none; background: var(--ant-review-hover); font-size: 12.5px; }
  & input::placeholder { color: var(--ant-review-faint); }
  & input:focus { box-shadow: inset 0 0 0 1.5px var(--ant-review-accent); }
  & input[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--ant-review-bad); }
  & button { height: 32px; padding: 0 12px; border-radius: 8px; font-weight: 680; font-size: 12.5px; background: var(--ant-review-ink); color: var(--ant-review-bg); }
}

/* step 3: projects */
.ant-review .ant-review-projs { display: grid; gap: 8px; }
.ant-review .ant-review-pj {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 8px 14px; padding: 13px 14px; border-radius: 13px; background: var(--ant-review-panel); box-shadow: inset 0 0 0 1px var(--ant-review-line);
  transition: box-shadow .3s;
  &.stalled { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--ant-review-bad) 55%, transparent); }
  &.hold { opacity: .6; }
  & .nm { display: flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 650; }
  & .nm i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); }
  & .st { font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; padding: 2px 7px; border-radius: 6px; }
  & .st.ok { color: var(--ant-review-good); background: color-mix(in oklch, var(--ant-review-good) 14%, transparent); }
  & .st.bad { color: var(--ant-review-bad); background: color-mix(in oklch, var(--ant-review-bad) 14%, transparent); }
  & .st.hold { color: var(--ant-review-mute); background: var(--ant-review-hover); }
  & .bar { grid-column: 1 / -1; display: flex; align-items: center; gap: 10px; font-size: 11.5px; color: var(--ant-review-faint); font-variant-numeric: tabular-nums; }
  & .bar span { flex: 1; height: 5px; border-radius: 3px; background: var(--ant-review-line2); overflow: hidden; }
  & .bar span i { display: block; height: 100%; width: calc(var(--p) * 100%); background: var(--c); border-radius: inherit; }
  & .next { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--ant-review-mute); }
  & .next svg { width: 14px; height: 14px; color: var(--ant-review-faint); }
  & .next b { color: var(--ant-review-ink); font-weight: 560; }
  & form { grid-column: 1 / -1; display: flex; gap: 6px; }
  & form input { flex: 1; min-width: 0; height: 32px; padding: 0 10px; border: 0; border-radius: 8px; outline: none; font-size: 12.5px; background: var(--ant-review-bg); box-shadow: inset 0 0 0 1px var(--ant-review-line2); }
  & form input:focus { box-shadow: inset 0 0 0 1.5px var(--ant-review-accent); }
  & form input[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--ant-review-bad); }
  & form button { height: 32px; padding: 0 12px; border-radius: 8px; font-size: 12px; font-weight: 680; background: var(--ant-review-accent); color: var(--ant-review-on); }
  & .side { display: flex; align-items: center; gap: 6px; }
  & .side button { height: 26px; padding: 0 9px; border-radius: 7px; font-size: 11.5px; font-weight: 640; color: var(--ant-review-mute); box-shadow: inset 0 0 0 1px var(--ant-review-line2); }
  & .side button:hover { background: var(--ant-review-hover); color: var(--ant-review-ink); }
}

/* step 4: planner */
.ant-review .ant-review-plan { display: grid; grid-template-columns: 210px repeat(5, minmax(0, 1fr)); gap: 8px; min-height: 100%; align-items: stretch; }
.ant-review .ant-review-zone {
  display: flex; flex-direction: column; gap: 6px; min-width: 0; padding: 8px; border-radius: 14px; background: var(--ant-review-panel); box-shadow: inset 0 0 0 1px var(--ant-review-line);
  transition: box-shadow .2s, background .2s;
  &.over { background: color-mix(in oklch, var(--ant-review-accent) 10%, var(--ant-review-panel)); box-shadow: inset 0 0 0 1.5px var(--ant-review-accent); }
  &.back { background: transparent; box-shadow: inset 0 0 0 1px var(--ant-review-line2); }
  & header { display: grid; gap: 5px; padding: 2px 2px 4px; }
  & header .hd { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; }
  & header b { font-size: 13px; font-weight: 700; }
  & header b em { font-style: normal; font-weight: 500; color: var(--ant-review-faint); margin-left: 3px; }
  & header output { font-size: 11px; font-variant-numeric: tabular-nums; color: var(--ant-review-faint); white-space: nowrap; }
  & header .cap { position: relative; height: 5px; border-radius: 3px; background: var(--ant-review-line2); overflow: hidden; }
  & header .cap i { position: absolute; inset: 0 auto 0 0; width: min(100%, calc(var(--u) * 100%)); background: var(--ant-review-good); border-radius: inherit; transition: width .5s var(--ant-review-spring), background .3s; }
  &.full header .cap i { background: var(--ant-review-accent); }
  &.hot header .cap i { background: var(--ant-review-bad); }
  &.hot header output { color: var(--ant-review-bad); font-weight: 650; }
  & .here { height: 26px; border-radius: 7px; font-size: 11.5px; font-weight: 700; color: var(--ant-review-on); background: var(--ant-review-accent); animation: ant-review-pop .35s var(--ant-review-spring); }
  & .drop { flex: 1; min-height: 40px; display: grid; place-items: center; border-radius: 9px; border: 1.5px dashed var(--ant-review-line2); font-size: 11px; color: var(--ant-review-faint); text-align: center; padding: 6px; }
}
.ant-review .ant-review-cardt {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr); gap: 4px; width: 100%; padding: 8px 9px; border-radius: 9px; text-align: left; background: var(--ant-review-bg); box-shadow: inset 0 0 0 1px var(--ant-review-line2);
  cursor: grab; touch-action: none; user-select: none; transition: box-shadow .2s, opacity .2s;
  & .tt { font-size: 12px; font-weight: 600; line-height: 1.3; text-wrap: pretty; }
  & .mt { display: flex; align-items: center; justify-content: space-between; gap: 6px; font-size: 10.5px; color: var(--ant-review-faint); font-variant-numeric: tabular-nums; }
  & .mt i { width: 7px; height: 7px; border-radius: 2px; background: var(--c); margin-right: 4px; }
  & .mt span { display: inline-flex; align-items: center; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &:hover { box-shadow: inset 0 0 0 1px var(--ant-review-faint); }
  &[aria-pressed="true"] { box-shadow: inset 0 0 0 2px var(--ant-review-accent); }
  &.lifted { opacity: .25; }
  &.fixed { cursor: default; background: transparent; box-shadow: inset 0 0 0 1px var(--ant-review-line); }
  &.fixed .tt { color: var(--ant-review-mute); }
}
.ant-review .ant-review-ghost {
  position: absolute; z-index: 90; left: 0; top: 0; width: 170px; pointer-events: none; display: grid; gap: 4px; padding: 8px 9px; border-radius: 9px;
  background: var(--ant-review-panel); box-shadow: inset 0 0 0 1.5px var(--ant-review-accent), 0 18px 34px -12px #000; font-size: 12px; font-weight: 600;
  translate: var(--x) var(--y); rotate: var(--r, 0deg); transition: rotate .2s;
}
.ant-review .ant-review-hint { margin-bottom: 10px; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; font-size: 11.5px; color: var(--ant-review-faint);
  & span { display: inline-flex; align-items: center; gap: 4px; }
}

/* step 5: intentions + done */
.ant-review .ant-review-rocks { display: flex; flex-wrap: wrap; gap: 6px; margin: 4px 0 18px;
  & button { display: inline-flex; align-items: center; gap: 7px; min-height: 34px; padding: 6px 12px; border-radius: 10px; font-size: 12.5px; font-weight: 600; text-align: left; color: var(--ant-review-mute); box-shadow: inset 0 0 0 1px var(--ant-review-line2); transition: background .2s, color .2s, box-shadow .2s, scale .3s var(--ant-review-spring); }
  & button small { color: var(--ant-review-faint); font-weight: 500; }
  & button:hover:not(:disabled) { color: var(--ant-review-ink); background: var(--ant-review-hover); }
  & button:active:not(:disabled) { scale: .96; }
  & button[aria-pressed="true"] { color: var(--ant-review-on); background: var(--ant-review-accent); box-shadow: none; }
  & button[aria-pressed="true"] small { color: color-mix(in oklch, var(--ant-review-on) 70%, transparent); }
}
.ant-review .ant-review-theme { display: grid; gap: 8px; max-width: 520px;
  & input { height: 42px; padding: 0 14px; border: 0; border-radius: 11px; outline: none; font-size: 15px; background: var(--ant-review-panel); box-shadow: inset 0 0 0 1px var(--ant-review-line2); }
  & input:focus { box-shadow: inset 0 0 0 1.5px var(--ant-review-accent); }
  & .sugg { display: flex; flex-wrap: wrap; gap: 6px; }
  & .sugg button { height: 26px; padding: 0 10px; border-radius: 99px; font-size: 12px; color: var(--ant-review-mute); background: var(--ant-review-hover); }
  & .sugg button:hover { color: var(--ant-review-ink); }
}
.ant-review .ant-review-done {
  display: grid; justify-items: center; gap: 14px; padding: 26px 20px; text-align: center;
  & .medal { position: relative; width: 84px; height: 84px; display: grid; place-items: center; border-radius: 50%; background: var(--ant-review-accent); color: var(--ant-review-on); animation: ant-review-medal .9s var(--ant-review-spring) both; }
  & .medal svg { width: 40px; height: 40px; stroke-width: 2.2; }
  & .medal::after { content: ""; position: absolute; inset: -10px; border-radius: 50%; border: 2px solid var(--ant-review-accent); opacity: 0; animation: ant-review-ring 1.4s var(--ant-review-ease) .3s; }
  & h2 { font-size: 26px; font-weight: 760; letter-spacing: -.03em; text-wrap: balance; }
  & p { color: var(--ant-review-mute); max-width: 52ch; text-wrap: pretty; }
  & dl { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; width: min(640px, 100%); margin: 6px 0 0; }
