  & dt { font-size: 22px; font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & dd { margin: 0; font-size: 11.5px; color: var(--ant-review-faint); }
  & ol { display: grid; gap: 4px; width: min(520px, 100%); text-align: left; }
  & ol li { display: flex; gap: 10px; align-items: center; padding: 8px 12px; border-radius: 10px; background: var(--ant-review-hover); font-weight: 600; }
  & ol li span { color: var(--ant-review-accent); font: 700 12px ui-monospace, Menlo, monospace; }
}
.ant-review .ant-review-done .open { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 6px; font-size: 12.5px; color: var(--ant-review-faint);
  & button { height: 28px; padding: 0 11px; border-radius: 8px; font-weight: 650; color: var(--ant-review-ink); box-shadow: inset 0 0 0 1px var(--ant-review-line2); }
  & button:hover { background: var(--ant-review-hover); }
}
@keyframes ant-review-medal { from { scale: 0; rotate: -30deg; } }
@keyframes ant-review-ring { 0% { opacity: .9; scale: .8; } 100% { opacity: 0; scale: 1.4; } }
.ant-review .ant-review-toast {
  position: absolute; z-index: 80; left: 50%; bottom: 70px; translate: -50% 0; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
  padding: 7px 7px 7px 14px; border-radius: 12px; background: var(--ant-review-ink); color: var(--ant-review-bg); font-size: 12.5px; font-weight: 600;
  box-shadow: 0 16px 34px -14px #000; transition: translate .5s var(--ant-review-spring), opacity .2s;
