  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & button { flex: none; height: 26px; padding: 0 10px; border-radius: 7px; font-weight: 750; background: var(--ant-review-accent); color: var(--ant-review-on); }
