  .ant-review .ant-review-in .acts { justify-content: flex-start; }
  .ant-review .ant-review-done dl { grid-template-columns: repeat(2, 1fr); }
  .ant-review .ant-review-zone { flex-basis: min(240px, 78cqi); }
}

@media (prefers-reduced-motion: reduce) {
  .ant-review *, .ant-review *::before, .ant-review *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important; }
  .ant-review .ant-review-done .medal::after { display: none; }
}

