  n === 3 ? (stalled().length ? stalled().length + ' stalled' : 'All moving') : n === 4 ? (S.tasks.filter(t => t.at === 'back').length + ' left to place') : (S.rocks.length + ' of 3 chosen');

/* ── shell ── */
