/* ── step 2 ── */
const WEEK = [['Mon', 6, 4.5, 2], ['Tue', 4, 3, 3], ['Wed', 7, 5, 1], ['Thu', 3, 2.5, 2.5], ['Fri', 4, 3.5, 1]];
