  return '<button type="button" class="ant-review-cardt" data-card="' + t.id + '" data-k="c' + t.id + '" aria-pressed="' + (S.sel === t.id) + '" aria-label="' + esc(t.title) + ', ' + h1(t.est) + ' hours. Press 1 to 5 to schedule, 0 for backlog">' +
    '<span class="tt">' + esc(t.title) + '</span><span class="mt"><span>' + (P ? '<i style="--c:' + P.c + '"></i>' + esc(P.name) : t.from ? 'From the inbox' : 'No project') + '</span><span>' + h1(t.est) + 'h</span></span></button>';
