      '<header><div class="hd"><b>' + title + (sub ? '<em>' + sub + '</em>' : '') + '</b><output>' + (cap != null ? h1(used) + ' / ' + h1(cap) + 'h' + (over ? ' · +' + h1(used - cap) : '') : L.length + ' left') + '</output></div>' +
