    ['Ship it, then breathe', 'Fewer meetings, deeper work', 'Finish before starting'].map(x => '<button type="button" data-k="s' + x.length + '" data-sugg="' + esc(x) + '">' + esc(x) + '</button>').join('') + '</div></div>';
