function renderDone() {
  const P = planned(), hrs = P.reduce((n, t) => n + t.est, 0), proc = Object.values(S.processed).reduce((a, b) => a + b, 0), open = [1, 2, 3, 4, 5].filter(n => !stepDone(n));
