    '<dl><div><dt>' + proc + '</dt><dd>inbox items processed</dd></div><div><dt>' + S.wins.length + '</dt><dd>wins noted</dd></div><div><dt>' + S.projects.filter(p => !p.hold && p.next.trim()).length + '/' + S.projects.length + '</dt><dd>projects moving</dd></div><div><dt>' + h1(hrs) + 'h</dt><dd>planned across 5 days</dd></div></dl>' +
    (S.rocks.length ? '<ol>' + S.rocks.map((id, i) => '<li><span>0' + (i + 1) + '</span>' + esc(S.tasks.find(t => t.id === id).title) + '</li>').join('') + '</ol>' : '') +
