/* ── toast & undo ── */
let tt = 0;
function toast(msg, canUndo) { const t = $('[data-toast]'); $('[data-tmsg]').textContent = msg; t.classList.toggle('no-undo', !canUndo); t.hidden = false; clearTimeout(tt); tt = setTimeout(() => { t.hidden = true; }, 3600); }
function undo() { if (!last) return; const s = last.s; s.visited = new Set(s.visited); S = s; last = null; render(false); toast('Undone', false); }

/* ── drag ── */
let drag = null;
root.addEventListener('pointerdown', e => {
  const c = e.target.closest('button[data-card]'); if (!c || e.button !== 0) return;
  drag = { id: c.dataset.card, el: c, x0: e.clientX, y0: e.clientY, on: false, pid: e.pointerId, lastX: e.clientX };
});
root.addEventListener('pointermove', e => {
  if (!drag) return;
  const dx = e.clientX - drag.x0, dy = e.clientY - drag.y0;
  if (!drag.on) {
    if (Math.hypot(dx, dy) < 5) return;
    drag.on = true; drag.el.classList.add('lifted');
    try { drag.el.setPointerCapture(drag.pid); } catch (err) {}
    const g = $('[data-ghost]'), t = S.tasks.find(x => x.id === drag.id); g.textContent = t.title + ' · ' + h1(t.est) + 'h'; g.hidden = false;
  }
  const rr = root.getBoundingClientRect(), g = $('[data-ghost]');
  g.style.setProperty('--x', (e.clientX - rr.left - 40) + 'px'); g.style.setProperty('--y', (e.clientY - rr.top - 18) + 'px');
  g.style.setProperty('--r', Math.max(-6, Math.min(6, (e.clientX - drag.lastX) * .6)) + 'deg'); drag.lastX = e.clientX;
  const under = doc.elementFromPoint(e.clientX, e.clientY), z = under && under.closest && under.closest('[data-zone]');
  $$('[data-zone].over').forEach(x => { if (x !== z) x.classList.remove('over'); });
  if (z && root.contains(z)) z.classList.add('over');
  drag.zone = z && root.contains(z) ? z.dataset.zone : null;
});
function endDrag(cancel) {
  if (!drag) return;
  const d = drag; drag = null;
  $('[data-ghost]').hidden = true; $$('[data-zone].over').forEach(x => x.classList.remove('over'));
  if (!d.on) return;
  d.el.classList.remove('lifted'); d.el.dataset.dragged = '1';
  if (!cancel && d.zone) moveTask(d.id, d.zone, 'drag');
}
root.addEventListener('pointerup', () => endDrag(false));
root.addEventListener('pointercancel', () => endDrag(true));

/* ── events ── */
root.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b || !root.contains(b)) return;
  const d = b.dataset;
  if (d.dragged) { delete d.dragged; return; }
  if (d.go) { S.step = +d.go; S.finished = false; S.visited.add(S.step); S.sel = null; render(); return $('[data-head] h2') && $('[data-body]').scrollTo(0, 0); }
